//     ★69로 수로가 6.4(계단 2.0 + 선반·난간 2.2×2)가 되면서 비가 **1.25배**로 떨어졌다. 원인이 사라졌다.
export const KW_ENTRY_W   = 2.00
export const KW_ENTRY_HW  = 4.00   // ★z 반폭 — **z=0 대칭**(현도 07.25 "저 판떼기 비대칭적이고 착지에 도움이 안 된다").
//  구판은 z −1~+4로 한쪽으로만 4 뻗은 슬래브라 착지판이 아니라 '남은 다리'로 읽혔다. 나선 도착(z 3.29)을
//  덮으려면 4가 필요하고, 대칭이면 반대쪽도 4다 → 3.0 × 8.0 판. 관(반폭 ≈5.7) 안이다.
