// ★1-③F 경사 완화(방향=ㄱ) · ★1-③G 드리프트 폐기: 계단 높이를 '가파른 리브 중심선'과 '나선끝→정션 곧은 현(chord)' 사이 블렌드.
//  0=리브 hug(시작 62°) · 1=곧은 현(시작 25°). 1-③G에서 무릎길 z 드리프트를 판넬로 폐기(중앙 정렬) → 옆쏠림 없어져 관 여유↑ → 시작 35°(F=0.84)까지 관 안(모서리 5.7<6).
//  대가: 계단이 리브 중심축에서 아래로 뜸(현도 승인). ↑=완만하나 리브 밖 삐질 위험 — 로컬 보행 노브.
// ════════ ★65 무릎길 몸(2026.07.25) — §2-D 마감 문법 적용 · 현도 "둘 다 구현하고 로컬 판정" ════════
//  ★진단: 무릎길 435칸은 균일하게 뜬 게 아니라 관 안에서 **계곡**을 그린다 — 양끝은 관 한복판에 떠 있고
//   앞쪽 1/4(118칸)은 이미 관 바닥에 닿아 있다. 실측 여유: 나선끝 4.49 · 배(x≈261) **0.11** · 정션끝 3.71.
//  ★그래서 ㊿ 하강로식 '깊이 2.6 등단면 스트링거'는 **이 구간에서 기하학적으로 불가능**하다.
//   살 있는 관 내벽 축거리 5.4971 − 무릎길 최대 5.491 = **여유 0.006**. 몸을 아래로 내밀려면
//   RIB_WALL_T를 0.15 밑으로 깎아야 하는데 그건 현도 반려선("다시 종잇장")이다.
//  ★두 안(같은 구성의 파라미터 두 벌 — 코드 경로가 하나라야 비교가 공정하다):
//   (가) 'fill'   = 보행선 그대로(0.84·시작 35°) + 넓은 몸이 **관 내벽에 깎여** 배에서 소멸.
//                   뿌리 = ①접지(배는 관 바닥에 앉고, 양끝은 판이 받는다). 대가 = 관 바닥의 둥근 맛.
//   (나) 'girder' = 보행선을 올려(0.70·시작 42°) 자리를 사고 ㊿ 사다리꼴 배를 그대로 이식.
//                   뿌리 = ③지지체. 대가 = 현도가 62°→35°로 끌어내린 경사를 7° 되돌림.
//  ⚠KW_FLATTEN이 모드에서 파생되므로 **보행선 자체가 달라진다** — 웨이포인트·RIB_BORE_MAX_AX·R7이
//   전부 여기서 파생된다(하드코딩 금지 불변식). 모드를 돌리면 그 전부가 자동 추종해야 한다.
export const KW_BODY_ON   = true
export const KW_BODY_MODE = 'fill'         // ⛔'girder'는 ★66이 폐기했다(아래) — 스위치는 남기되 검증 T절이 실패로 문서화한다
//  ⛔★66 폐기 근거(2026.07.25, 산술): girder는 자리를 사려고 KW_FLATTEN을 0.70으로 올리는데, 그러면
//   스파인 시작 경사가 41.8°가 된다. 참이 성립하려면 flight가 스파인보다 가팔라야 하므로 경사 > 41.8°가
//   필요한데, 통례 2R+G ≥ 0.60은 경사 ≤ 40.8°를 요구한다. **교집합이 공집합**이다.
//   즉 girder 모드에서는 사람이 딛는 계단을 놓을 수 없다. 게다가 ★66의 참이 보행면을 이미 최대 1.45
//   들어올리므로(몸이 쓸 자리가 그만큼 늘었다) girder의 존재 이유였던 '자리 사기'도 사라졌다.
const _GIRDER = KW_BODY_MODE === 'girder'
export const KW_FLATTEN   = _GIRDER ? 0.70 : 0.84   // (가) 시작 35.2°·몸자리 0.16 / (나) 시작 41.8°·몸자리 1.03
//  몸 단면(보행선 기준 로컬 u=횡·v=종) — ㊿ DESC_GIRDER_* 어휘 계승
export const KW_BODY_HW   = _GIRDER ? 1.30 : 6.50   // 반폭. 'fill'은 관 반경(6)보다 커서 **관이 깎는다**(= 전폭)
export const KW_BODY_D    = _GIRDER ? 0.90 : 1.60   // 보행면 아래 최대 깊이. 이보다 깊어지면 관 내벽이 먼저 만난다
export const KW_BODY_BWF  = _GIRDER ? 0.62 : 1.00   // 밑폭 비(0~1) — 사다리꼴 배. 1이면 각재
export const KW_BODY_TOP  = 0.06           // 몸 상면 = 디딤판 밑면 + 이것 → 판이 0.06 파묻혀 융착(판 밑 틈이 구조적으로 없다, ㊿ ②)
export const KW_BODY_EXT  = 0.50           // 양끝 매듭 물림 — 판넬·정션 판 안으로 이만큼 파고들어 헤어라인 봉인
//  ★67: **정션쪽에만** 남는다. 나선쪽 테이퍼는 폐기 — 도입 참이 나선 마지막 디딤판을 흡수하므로
//   피해야 할 대상이 사라졌고, 그 테이퍼가 바로 "입구에서 가장 가늘어지는" 결함의 원인이었다.
export const KW_BODY_TAPER = 6.0   // 정션끝 테이퍼 길이(정션 판에 물릴 때 보행 폭으로 좁아진다)
export const KW_BODY_SEG  = 4              // 몇 칸마다 종단 표본 하나(435칸 → ≈109 표본). 보행선이 매끄러워 이 정도면 충분

// ★1-③G 착지 판넬(LandingPanel): 나선 옆끝(z=+STAIR_R)에서 무릎길 중앙(z=0)으로 가로지르는 솔리드 착지판.
//  나선 도착 → 판넬 건너 중앙 → 중앙 계단. 무릎길 z 드리프트 폐기(비스듬함 소멸) + 계단 옆쏠림 없어져 관 이탈도 해소.
export const PANEL_DX = 1.6                 // 판넬 x깊이(나선 도착 착지)
export const PANEL_Z0 = -KW_TREAD_W / 2     // z 시작(무릎길 중앙 가장자리)
export const PANEL_Z1 = STAIR_R + 0.7       // z 끝(나선 옆끝 너머)

// ── 착지 디스크: 이제 갈림(정션·U_KNEE_END) '한 곳'만. r=4.0 > 헬릭스 3.3.
//    ⚠1-③C: 나선끝(U_SPIRAL_END)에서는 폐기 — 축 위 솔리드 판이 나선(r3.3)을 덮어(r4.0) 위로 못 나가는
//    '뚜껑' 문제 → 나선끝은 아래 '부양 다리'로 교체(캡 없음). 정션 디스크도 같은 구조라 다음 조각 대상. ──
export const LAND_R = 4.0
export const LAND_T = ROOM_STAIR_SLAB      // 디스크 두께 = 방 디딤판(부양 판 어휘 공유)
// ★②-착지장(2026.07.06 재설계 v3, 스케치 확정): 사각 판. 세 계단이 판 가장자리에서 시작(관통 없음):
//  무릎길은 +x 변에 도착, 전망·하강은 −x 변에서 밖으로(−x) 나감(전망 위·하강 아래, 각자 제 z 그대로).
//  전망은 리브곡면 대신 '곧은 램프'로 바꿔 판 위로 가로지르지 않음. z 안 뒤집음 — 전망 −2.4·하강 +1.75·통로 그대로.
// ★x-커플링(2026.07.07): 이 두 변이 판의 정본 — 세 계단의 판쪽 끝이 전부 여기서 파생되어, 판을 넓혀도 계단이 항상 변에 붙는다.
//   · 무릎길 도착 = X_LAND_HI (Dome.jsx KneeWalk xB) · 하강 시작 = X_LAND_LO+0.2 (X_DESC0) · 전망 램프 시작 = X_LAND_LO (Dome.jsx Lookout).
//   넓히려면: X_LAND_HI ↑(+x 바깥) / X_LAND_LO ↓(−x 바깥). ⚠ X_LAND_LO엔 하강이 물려 있어, 움직이면 통로(하강→아치→전실→문) 전체가 −x로 같이 밀린다(테라스 높이는 y파생이라 무관).
//   X_LAND_HI는 무릎길 도착만 늘고 줄어 자기완결 — 착지 깊이만 넓히고 싶으면 이쪽을 권장.
export const X_LAND_LO = rOf(U_KNEE_END) - LAND_R + 1.5     // 판 −x 가장자리 = 전망·하강 출발 (기본값; 넓히려면 이 식에서 빼기)
//  ⛔★75에서 +5.79(판 +x변 192.80)로 늘리려다 **되돌렸다**(2026.07.26). 현도 아이디어였고 기하는 옳았다 —
//   사진의 "판 직전 의미 없는 짧은 수평 + 약간의 상승"은 무릎길의 마지막 참·flight이고, 그걸 판에 흡수하면
//   하강 시작을 동으로 밀어 상승 경사를 43.9°까지 낮출 수 있었다. **관이 거부했다.**
//   ⚠막은 것은 판이 아니라 **무릎길 자신의 층고**다: 판을 늘리면 무릎길 주행이 짧아져 보행면이 관 안에서
//    올라오고 층고를 먹는다. 실측 — 190.51에서 2.34(이미 아슬아슬) · 191.01에서 2.13 · 192.80에서 **1.44**
//    (눈높이 1.6이므로 머리 위 −0.16 = 통행 불가). 한계는 190.84이고 거기서 얻는 건 47.55°→47.2° = 0.35°.
//   ★교훈: 무릎길을 건드리기 전 블롱델·참만 재고 **층고를 안 쟀다.** 세 지표를 함께 재야 한다.
//  ★★2026.07.26 현도: "갈림판이 왜 하나의 판이 아니며 단차가 있는지 모르겠다."
//   → 아래 단(㊄-c 참 흡수)을 폐기하고 **판 자체를 동쪽으로 늘려 하나의 평면**으로 만든다.
//  ⚠`X_LAND_HI`는 **무릎길의 목표점**이라 건드리면 무릎길이 재유도돼 층고가 무너진다(실측 1.44).
//   그래서 판의 동쪽 끝만 별도 상수로 분리한다 — 무릎길 수학은 무손상.
//  ⚠확장 상한도 실측: 판(256.13) 위 층고가 x192.90에서 2.23, x193.50에서 1.94로 무너진다 → 2.39가 상한.
export const JCT_PLATE_EXT = 2.39                                // 판 +x 확장량(층고 실측 상한)
export const X_LAND_HI = rOf(U_KNEE_END) + 3.5                   // ★무릎길 **도착점**(kneeStair의 목표) ③≈190.51 — ★75에서 판 끝과 분리됐다
export const JCT_PLATE_XHI = X_LAND_HI + JCT_PLATE_EXT           // ★판의 +x 끝 ③≈192.90
export const Z_LAND    = 4.5                                // 판 z 반폭 — 전망(−2.4)·하강(+1.75) 둘 다 판 위에 담게

// ── ★70 정션 매듭(2026.07.25): 착지장 밑의 받침 매스 — §2-D ③ 두께 위계를 정션에서 세운다 ──
//  ⚠적발: 무릎길이 세 단(걷는 것 0.20 < 받치는 것 1.60 < 매듭 2.60)을 세워 놓았는데, 판 하나 건너
//   정션 착지장은 LAND_T **0.35**로 떨어진다 — 여정에서 가장 큰 마디(세 갈래가 만나는 곳)가 가장 얇았다.
//  ★수법은 ★67과 같다: **걷는 면은 얇게 두고 아래를 두껍게.** LAND_T는 손대지 않는다
//   (전망 디스크·LK_DISC_LIFT가 물려 있어 건드리면 1p8 전망이 따라 움직인다) — 밑에 매스를 단다.
//  ★한 연산이 두 형태를 낸다(★65와 같은 설계): 판 발자국 각기둥 ∩ 관 안쪽 솔리드.
//   'knot' = 무릎길 매듭과 같은 2.60(관이 모서리만 스친다) / 'fill' = 관이 밑면을 통째로 깎는다
//   (= 갈림이 떠 있는 판이 아니라 **리브가 땅이 되는 자리**가 된다). 로컬 판정용 두 벌.
// ── ★72 정션 판 윤곽(2026.07.25, 현도 지시 "관에 맞춰라") ──
//  ⚠적발: 관은 **원(정10각)**인데 판은 **사각**이라 네 모서리가 관 내벽에서 각기 다른 거리로 떠 있었다
//   (+x변 0.96 · −x변 1.09 실측). 원통 안에 직사각형이 떠 있는 것이 "얹어놓은 것" 같아 보이던 이유.
//  ★실측: 판 높이에서 관의 z 반폭은 **5.48~5.76**으로 판(4.5)보다 사방 1.0~1.26 넓다 →
//   윤곽을 관에 맞추면 판이 **벽에 닿는다**(뜬 모서리 소멸). x 범위는 그대로 둔다 —
//   관 수평 단면은 x 176.9~199.6(길이 22.7)이라 전부 채우면 하강 23칸이 판 속에 파묻힌다.
//  ⚠벽에 **정확히** 맞추면 z파이팅이 난다 → `JCT_PLATE_FUSE`만큼 살 속으로 파고든다(★71-3 융착 어법).
export const JCT_PLATE_MODE = 'bore'      // 'bore'(관 단면 추종·기본) | 'rect'(구판 사각 — 비교용)
export const JCT_PLATE_FUSE = 0.10        // 관 내벽 안으로 파고드는 깊이(살 0.22보다 얕다)
export const JCT_PLATE_SEG  = 24          // 윤곽 표본 수

export const JCT_KNOT_ON   = true
export const JCT_KNOT_MODE = 'knot'         // 'knot'(기본·무릎길 매듭과 동일 두께) | 'fill'(관이 밑면을 깎음)
//  깊이 = 판 **윗면** 기준. 'fill'의 9.0은 판 발자국 최대 가용 깊이 8.53(+x변 중앙 실측)보다 커서
//   전 발자국에서 관이 먼저 만난다 = 밑면 전체가 깎인 면이 된다(§2-D ② '깎인 밑면').
export const JCT_KNOT_D    = JCT_KNOT_MODE === 'fill' ? 9.0 : KW_KNOT_D
export const JCT_KNOT_TOP  = KW_BODY_TOP    // 매스 상면 = 판 밑면 + 이것 → 판이 파묻혀 판 밑 틈이 구조적으로 없다(㊿ ②)
export const JCT_KNOT_INSET = 0.0           // 발자국 축소(0 = 판과 같은 발자국; +면 매스가 판 밑으로 물러남)

// ── 부양 다리(1-③C): 나선 마지막 칸 → 무릎길 첫 칸을 잇는 떠 있는 디딤판 몇 개(캡 디스크 대체).
//    나선 자리에 솔리드 판을 두지 않아 '뚜껑' 소멸 + 1p7 '증명된 뜸' 어휘 일관(전부 부양 디딤판).
//    개수 = 수평간격/BRIDGE_STEP 자동(θ_end 튜닝에 적응). Dome.jsx LandingBridge가 spiralPoint(끝)↔무릎첫칸 보간. ──
export const BRIDGE_STEP  = 1.0            // ★다리 디딤판 수평 간격 목표. ↓=디딤판 많아짐(더 촘촘·완만) / ↑=적어짐. ③에서 간격≈2.9 → 3개
export const BRIDGE_DEPTH = 1.6            // 다리 디딤판 진행방향 깊이(≥간격이라 겹쳐 끊김 없음)
export const BRIDGE_W     = 2.4            // 다리 디딤판 폭(나선 1.0 ↔ 무릎길 4.5 사이)

// ── 갈림(정션·u=U_KNEE_END): 디스크에서 두 갈래 — z 분리로 겹침 방지(관 중심선 현폭 12 안) ──
//  ★갈림 = 논증: 위로 무한히 올라도(1p8) 신에 닿지 않고, 되돌아 내려가(아치) 이행(1p9·10)을 거쳐야 1p11.
export const JCT_UP_Z  = -2.4              // 상행(1p8 전망) 갈래 z 오프셋 — 등반자 오른쪽(웨지 볼벽과 간극 0.25)
//  ★75(2026.07.26): +1.75 → **0**. 갈림이 좌우(z 분리)에서 **위·아래**로 바뀐다 —
//   넓은 상승 계단이 막다름(1p8)이고, 갈 길은 그 밑에 뚫린 아치다. 채널·볼벽 둘·아치 컷·방 입구가
//   전부 파생이라 이 한 줄로 따라온다.
//  ⚠**전 스위트 green은 안전의 증거가 아니었다**: ★74 봉인 검사는 볼벽 상단을 *판 기준 높이*로 잠글 뿐
//   시선을 안 잰다. 그래서 착수 전 `_probe_leak75.mjs`로 차분을 다시 쟀다 —
//   **1064 → 675(Δ−80)**. 봉인은 나빠지지 않는다(오히려 판이 채널 바로 위를 덮어 좋아진다).
//   ⚠그 결론에 이르기까지 모델이 두 번 틀렸다(회랑 누락 → +43 · 계단 판 58장 누락 → +94).
//    ★대장이 비면 차분의 **부호가 뒤집힌다** — 봉인 부재를 다 넣기 전엔 어떤 차분도 못 믿는다.
export const JCT_DN_Z  = +0.0              // 하강(아치→통로) 갈래 z 오프셋. 통로 전체가 이 z를 따름

// ── 1p8 전망(막다름): 갈림에서 관축을 따라 계속 상행, 경사 1.2(가파른 계단 한계)에서 종단 + 플랫폼.
//    ③에서 u≈0.2756 · y≈264.6 · 등반 8.5 · 24칸. 플랫폼에서 올려다보는 보어 ≈ 695 = 눈높이 435배(suo genere) ──
export const LOOKOUT_MAX_SLOPE = 1.2
export const U_LOOKOUT_END = KNEE + WIDTH * Math.acosh(Math.sqrt(LOOKOUT_MAX_SLOPE / SLOPE_KNEE_MIN))
export const LK_STEPS  = Math.max(6, Math.round((U_LOOKOUT_END - U_KNEE_END) * H / STEP_RISE))
export const LK_PLAT_R = 5.5               // 전망 플랫폼 반지름(중심선 위) — 1p8 비석 자리(Phase 2)
// ★②(2026.07.06) 전망 디스크 뚜껑 해소(A 방향): 디스크를 살짝 띄워 밑면이 '끝 전망 스텝' 위를 지나게 →
//  스텝(z=−2.4)이 디스크(z=0, r3.2) 밑으로 들어가 24칸 중 6칸이 판 밑에 깔리고 끝 스텝이 판을 뚫던 겹침 소멸.
//  판 z=0 유지(보어 올려다보기 = 중심에서 위 보기). 올라서기 = 끝스텝 top → 판 top ≈0.40 (STEP_UP 0.8 안).
// ★71(2026.07.25) 전망 판 두께 분리 — 현도 "반원 판은 두께를 가지도록 수정해야해, 현재는 종잇장".
//  ⚠구판은 정션 판과 `LAND_T`(0.35)를 **공유**했다. 지름 11 대비 1:31이라 종잇장으로 읽힌 것이 맞다.
//   정션 판까지 같이 두꺼워지면 안 되므로 상수를 가른다. 아래 LK_DISC_LIFT가 이 값의 파생이라
//   **두께를 키우면 판 윗면이 올라가고 램프가 저절로 따라온다**(Lookout이 디스크 윗면을 조준).
export const LK_DISC_T = 1.2               // 전망 반원 판 두께(구 LAND_T 0.35) — 지름 11 대비 1:9.2
export const LK_TOPSTEP_TOP = U_KNEE_END * H + LK_STEPS * STEP_RISE + TREAD_THICK / 2   // 끝 전망 스텝 윗면 ③≈264.5
export const LK_DISC_LIFT   = Math.max(0.1, LK_TOPSTEP_TOP + 0.05 + LK_DISC_T - U_LOOKOUT_END * H)  // 디스크 밑면 = 끝스텝+0.05
// ★전망 디스크 반원화·이동(2026.07.07, 현도 손튜닝): 반원 여부 + 앞뒤(−x)·위(+y)·옆(z)·회전. 램프가 디스크의 램프쪽 가장자리(지름변)에 맞닿아 따라옴(Lookout 재작성).
export const LK_DISC_HALF = true    // true=반원(평평한 변에 램프 닿음) / false=온전한 원
export const LK_DISC_DX   = -2.0       // 앞뒤: − = 돔 중심(앞)으로 / + = 뒤로 (디스크 x = rOf(U_LOOKOUT_END) + 이 값)
export const LK_DISC_DY   = +2.5       // 위아래: + = 위(높이)
export const LK_DISC_DZ   = 0       // 옆(수평 z): 램프(z=−2.4)에 붙이려면 음수 쪽으로
export const LK_DISC_ROT  = 0       // 반원 평평한 변 회전(rad): 지름변을 램프 쪽으로 돌려 맞춤

// ── ★71 빛 기둥(2026.07.25, 현도 아이디어): 전망 반원 판 → 전실 방까지 뚫린 관 ──
//  현도: "위로 뻗은 리브에서 새어나오는 빛이 하강길 끝 직육면체 방까지 이어지도록. 반원 판 중간에
//   원기둥 혹은 원뿔대를 세우고(윗면이 판에 딱 맞게) 방까지 통과. 반원 판을 지지까지 해준다."
//  ⚠**빛나는 장치는 안 만든다**(현도 명시) — 기하는 '뚫린 관'까지고, 빛은 P2 조명 게이트 몫이다.
//   1p10 등불(`LAMP_*` 반경 0.7·매달림·자체 발광)과는 **굵기와 접지로 갈린다**(현도 판정: 겹쳐도 무방,
//   오히려 전실에서 하나 → 회랑에서 넷의 **예고편**으로 작용).
//
//  ★★LOCKED 예외 #4 — 목적지 리브 껍질 관통(현도 승인 2026.07.25).
//   근거 = 예외 #1·#2와 **같은 형식**: "갈림길 권역의 리브는 1p11 공개 이전 어느 시점에서도 밖에서
//   보이지 않는다"(현도). 경계는 검증(K절 확장)이 강제한다 — 조건이 깨지면 검사가 먼저 빨개진다.
//   ⚠★59에서 '리브 창'이 1p6 용도로 폐기된 사유(바깥면 관통)와 같은 지점이므로, 이 예외는
//    **불가시가 실측으로 유지되는 한에서만** 유효하다. 위치·굵기를 키우면 재검할 것.
export const SHAFT_ON     = true
export const SHAFT_MODE   = 'column'    // 'column' 원기둥 | 'capital' 원뿔대(위가 넓음 = 받침머리) — 현도 로컬 판정
export const SHAFT_R      = 1.5         // 아래 반경. ⚠2.0 넘으면 방 통행이 좁아진다(입 여유 1.04 실측)
export const SHAFT_R_TOP  = 2.3         // 'capital'일 때 판에 닿는 위 반경
export const SHAFT_HOLLOW = true        // 뚫린 관(현도 "그냥 뚫린 것으로") / false = 속 찬 기둥
export const SHAFT_WALL_T = 0.45        // 관 살 두께(HOLLOW일 때)
//  ★71-3(현도 로컬 판정 2026.07.25): *"반원과 기둥 사이에 미세한 틈이 있어. 리브도 마찬가지."*
//  ★★진단 = 여유의 부호가 틀렸다. 헤어라인이라도 **여유는 여유라서 틈으로 보인다**(★64 교훈의 반쪽만
//   적용했던 것). 구멍을 관보다 **작게** 뚫어 관이 파고들게 한다 = ㊿ '융착' 어법(판 0.43이 0.13 융착).
//   겹친 두 솔리드는 이음매가 **원리적으로** 안 보인다 — 가릴 것이 없기 때문이다.
export const SHAFT_FUSE   = 0.06        // 관이 구멍보다 이만큼 크다(=파고든다). 구 SHAFT_CLR 0.08(여유)의 부호 반전
//  ★71-4 격자 체(현도 제안): 판에 뚫린 지름 3 구멍을 덮어 **밟을 수 있게** 하면서 빛은 통과시킨다.
//   ⚠§2-C 위반 아님 — 그 금지(수직 립 배열)는 **세로** 요소에 대한 것이고 이건 수평 부재다.
export const SHAFT_GRATE_ON  = true
export const SHAFT_GRATE_BAR = 0.14     // 살 폭
export const SHAFT_GRATE_GAP = 0.42     // 살 간격(빈틈) — 발이 안 빠지는 하한
export const SHAFT_GRATE_T   = 0.18     // 살 두께(판 윗면 아래로 잠긴다)
//  ★위치 = 반원의 **도심**이지 중심점이 아니다. thetaStart π라 반원은 중심에서 −x 절반만 채우므로
//   중심점(x 174.62)은 램프가 도착하는 **가장자리**다. 도심 = 중심 − 4R/3π.
export const SHAFT_X = rOf(U_LOOKOUT_END) + LK_DISC_DX - 4 * LK_PLAT_R / (3 * Math.PI)   // ③≈172.28
export const SHAFT_Z = LK_DISC_DZ

// ── 하강 + 연결 통로(공개 전실): 디스크 가장자리(x=rOf(U_KNEE_END)−LAND_R)에서 −x로 경사 1.15, 8.0 하강.
//    ★아치 입은 '외부'가 아니라 보어를 향한다(하부 벽 관통) → 후드 불필요, 상자 외피가 바깥을 봉함.
//    ★TERRACE_Y = 통로 바닥에서 '파생'(자유 요소 확정 — 접속 경사 문제가 정의상 소멸, 구 H·KNEE=240 → ≈248) ──
export const DESC_DROP    = 8.0            // 하강고 — 전실 지붕(바닥+5.5)이 갈림 디스크(y256) 아래로 깔리는 최소치
                                           //  ⚠★75: 하강 시작·경사가 이 값의 파생이 됐으므로 **아래 블록보다 먼저** 선언한다

// ════════ ★75-a 계단 발치 · 아치 요구치 (2026.07.26) — **하강보다 먼저 선언한다** ════════
//  ⚠하강이 이 값을 소비하므로 순서가 뒤바뀌면 TDZ다(㉒ 전례).
//  ★★왜 하강이 계단을 따라야 하나(이 세션의 핵심 발견):
//   계단은 바닥에서 솟는다 → **발치에서 계단 상면 = 바닥 = 높이 0**이다. 그 밑으로 지나갈 수 없다.
//   아치가 서려면 하강이 **발치에 닿기 전에 이미** (머리 + 크라운 위 살)만큼 내려가 있어야 한다.
//   브리프는 "계단 밑 머리 여유 3.0"을 **계단 상면까지** 재서 이 조건을 놓쳤다 — §2-D 매스(깊이 1.6)를
//   붙이는 순간 밑면은 그만큼 내려오고, 발치에서는 −1.37 = 터널이 물리적으로 불가능해진다.
export const WARCH_CLEAR = 2.2      // 터널 머리 여유(눈 1.6 + 머리 + 여유)
export const WARCH_HEAD  = 0.55     // 아치 크라운 위에 남길 살 — 계단 상면과 아치 사이의 두께
export const WSTAIR_FOOT_DROP = WARCH_CLEAR + WARCH_HEAD                        // ③ 2.75

// ════════ 하강 — ★75로 **규격 재유도**(일지 ㅠ 항목이 ★75에 끌려 들어옴) ════════
//  ⛔구값 폐기: `DESC_SLOPE` 1.15(49°) · `STEP_RISE` 0.35 파생 23칸 → **2R+G = 1.00 = 석조 통례의 157%**,
//   디딤 1.5가 0.30씩 전진해 판이 4.93배 겹치는 "톱니 경사면"이었다(DESIGN이 세 세션째 적어 온 결함).
//  ★해소는 조형이 강제했다: 아치를 세우려 하강 시작을 계단 발치 동쪽으로 밀었더니
//   경사가 49° → **29°**로 떨어지고 2R+G가 통례 안으로 들어왔다. 한 조작이 둘을 푼다.
//  ⚠`DESC_SLOPE` 1.15 주석의 *"가파름 = 압축의 시작"*은 의도값이었다 — 현도 판정으로 해제(2026.07.26).
//  ★★파생 방향이 ★75에서 **뒤집혔다**: 예전엔 하강 시작이 입력이고 경사가 노브였다.
//   이제는 **도착 평지가 입력**이고, 하강 시작 → 계단 발치 → 두 경사가 전부 그 파생이다.
//   근거: 계단은 바닥에서 솟으므로 발치 밑으로 지나갈 수 없고, 발치에 닿기 전에 이미 FOOT_DROP만큼
//   내려가 있어야 한다. 그 한 줄이 이 권역의 모든 치수를 정한다.
export const JCT_ARRIVE_L = 0.6     // ★도착 평지: 무릎길에서 올라서서 계단우물 앞까지. 이게 이 권역의 유일한 자유도다
//  ★2026.07.26 현도: "하강 각도는 더 가파르게 해도 될 것 같아. 지금은 약간 완만해."
//   ⛔구 체제는 도착을 동결하고 경사를 파생시켰다 → 33.3°까지 완만해졌다(구 49°의 반대 극단).
//   ★이제 **경사가 입력**이고 도착이 파생이다. 방 +x벽이 따라 커진다(현도 승인: "직육면체 방만 변화").
//  ★★뜻밖의 이득: 하강을 세우면 **상승도 완만해진다.** 하강이 FOOT_DROP 2.75를 더 빨리 벌어서
//   계단 발치가 동쪽으로 갈 수 있기 때문이다. 실측 — 하강 33.3°→상승 47.6° · 42°→44.8° · 48°→43.5°.
//   두 계단의 경사가 서로 반대로 움직인다고 믿기 쉬운데, 실제로는 **같은 방향으로 개선된다.**
export const X_DESC0      = X_LAND_HI - JCT_ARRIVE_L                            // ③≈189.91
export const DESC_SLOPE_DEG = 42.0   // ★하강 경사(노브). 세울수록 상승도 완만해지고 방이 커진다
export const X_DESC_END   = X_DESC0 - DESC_DROP / Math.tan(DESC_SLOPE_DEG * Math.PI / 180)   // ③≈181.03
//  계단 발치 = "발치에서 FOOT_DROP만큼 내려와 있다"의 해(위 식의 역):
export const WSTAIR_X0    = (X_DESC0 * (DESC_DROP - WSTAIR_FOOT_DROP) + WSTAIR_FOOT_DROP * X_DESC_END) / DESC_DROP   // ③≈187.23
export const DESC_SLOPE   = DESC_DROP / (X_DESC0 - X_DESC_END)                  // = tan(DESC_SLOPE_DEG)
export const PASS_FLOOR_Y = U_KNEE_END * H - DESC_DROP                          // 통로 바닥(슬랩 윗면) ③≈248.0
//  블롱델 재유도: 2R+G = (2·DROP + RUN)/N 을 통례 0.60~0.68 한가운데(0.64)에 맞춘다
export const DESC_STEPS   = Math.max(6, Math.round((2 * DESC_DROP + (X_DESC0 - X_DESC_END)) / 0.64))   // ③에서 41
export const DESC_STEP_R  = DESC_DROP / DESC_STEPS                              // ③≈0.195  ⚠`DESC_R`은 ㊾ 드럼 하강로 반경이라 이름이 겹친다
export const DESC_STEP_G  = (X_DESC0 - X_DESC_END) / DESC_STEPS                 // ③≈0.251
//  ⚠디딤판 깊이도 같이 유도한다 — 구판은 `TREAD_DEPTH` 1.5가 G 0.30씩 전진해 6배 겹쳤다(= 톱니).
//   ★66의 코 비(1.17)를 계승해 겹침을 한 겹으로 만든다.
export const DESC_TREAD_D = DESC_STEP_G * 1.17                                       // ③≈0.294
// (구 DESC_SLOPE 선언 위치 — 위로 이관됨)





// 하강 채널 단면(z중심 = JCT_DN_Z, 내부 반폭 PASS_HW): 봉인 슬랩 + 측벽(구 볼벽) — 회랑판이 계승
