//   0.04~0.11 높은 자리에 걸린다(현도 적발 2026.07.26 · 실측 x 180.67~180.92 · y 253.27~253.34).
//   ⚠자르면 잘린 가장자리가 방에 노출되고, 안 자르면 살이 보인다 — **덮는 게 답이다.**
//   문틀을 서쪽으로 이만큼 늘려 그 구간을 벽 안에 넣는다(문 둘레가 두꺼워질 뿐, 개구는 그대로).
export const RM_MOUTH_REVEAL = 0.55
export const PASS_FUSE    = 0.06   // ★디딤판·바닥이 볼벽 살 속으로 무는 깊이. 0이면 동일 평면 = z-fighting(★75 적발)
export const PASS_T       = COR_THICK      // 판 두께 0.6(통로 외피 어휘 공유)
//  ★75(2026.07.26 현도 "아치 입구 여전히 비대칭 · 이상한 홈"): 좌우 볼벽이 **서로 다른 x까지** 뻗어 있었다
