//   z=0 대칭 채널이 된 뒤에는 근거가 없다. → **둘 다 이 값을 쓴다**(슬랩도 같이).
export const PASS_X_CHEEK = X_DESC0 + 0.5  // 볼벽·슬랩 공통 깊은 끝 ③≈190.41
// 바닥 슬랩 깊은 끝 = 리브 하부면이 바닥 높이(PASS_FLOOR_Y)와 만나는 x + 0.5(벽 물림) — ★디스크 아래 봉인
//  (스포 누출 지점: 슬랩이 짧으면 디스크 밑 웨지(슬랩 끝↔벽)로 시선이 빠짐 — 검증 ㉙에서 실측 발견)
export const PASS_X_DEEP = (() => {
  for (let uu = KNEE; uu < 0.32; uu += 0.0002) {
    const sl = SLOPE_KNEE_MIN * Math.cosh((uu - KNEE) / WIDTH) ** 2, nn = Math.hypot(1, sl)
    if (uu * H - SHELL_RIB_R / nn >= PASS_FLOOR_Y) return rOf(uu) - SHELL_RIB_R * sl / nn + 0.5
  }
  return X_DESC0 + 5.5
})()                                         // ③≈189.5
export const PASS_X_END   = TERRACE_ROUT_BASE + 0.5                              // 테라스 림 물림 반경(회랑판: 스텁 끝벽의 원점거리) ③≈158.9
//  볼벽 상단(비대칭): −z쪽은 갈림 디스크 하면(y+0.1−0.35) 아래로 제한, +z쪽은 디스크가 닿지 않아(r4 < z4.35)
//  높게 올려 입 상단 너머 +z 측면 시선을 봉쇄(검증 ㉙ 2차 누출 지점 — 커터 축소와 짝).
//  ⛔★75(2026.07.26 현도: "아치 양 옆 벽이 약간 비대칭이지?"): −0.6(255.43) → 판 윗면.
//   +z는 ★75에서 이미 판 윗면(256.13)으로 평평해졌는데 −z만 0.70 낮게 남아 **한쪽이 처진 문틀**이 됐다.
//   구 −0.6의 근거는 "정션 판 하면 아래로 숨긴다"였는데, ★75가 판에 계단우물을 뚫으면서 숨을 이유가 사라졌다.
export const CHEEK_TOP_NZ = U_KNEE_END * H + 0.1                            // = +z와 같은 높이(대칭) ③≈256.13
//  ★74(2026.07.25, 현도 로컬 판정 "파란색이 가장 튀어나온 벽"): +z 볼벽 상단을 **정션 판 윗면**에 맞춘다.
//  ⚠구 +1.5(257.53)는 판 윗면보다 **1.4 높아** 갈림판 바닥을 뚫고 올라와 있었다 — 그게 "튀어나옴"의 정체.
//  ★그 높이의 근거는 주석에 이렇게 적혀 있었다: *"+z쪽은 **디스크가 닿지 않아(r4 < z4.35)** 높게 올려"*.
//   ★72가 판을 |z| 5.58~5.88까지 넓혀 **그 전제가 소멸**했다(볼벽 z 4.35를 판이 덮는다).
//  ★차분 광선 재측정(포함 판정·표본 0.1·방위 90×고도 10): 257.53→256.13 **누출 Δ0** · 255.5부터 +6.
//   여유 0.63. ⚠이보다 더 낮추지 말 것 — 관을 벗어나는 칸 12(x 180.9) 이후엔 이 벽이 유일한 차폐다.
//  ⚠구 모델 두 벌이 여기서 **둘 다 틀렸다**: 표본 0.2는 살(0.22)을 건너뛰고, 교차 판정은 안쪽 경계(5.78)가
//   아니라 바깥(6.0)을 봐서 관통을 못 잡았다. 살은 **포함 판정 + 표본 < 두께**로만 정확히 잡힌다.
export const CHEEK_TOP_PZ = U_KNEE_END * H + 0.1                            // = 정션 판 윗면 ③≈256.13(낮은 쪽)
//  ★단차 대신 **레이크(경사 상단)**로 잇는다 — 낮춘 구간과 남긴 구간을 그냥 이으면 1.4 단차가 새 어색함이 된다.
//   x0(관 밖 구간)에서 구 높이 유지 → x1(판 −x변)에서 판 윗면. 실측: 이 형상도 누출 Δ0(방위 120×고도 13).
//  ⛔★75 제거(2026.07.26 현도: "갈림판 옆 거슬리는 난간 구조물"). 판보다 1.40 솟아 있었고,
//   −z 볼벽은 판보다 0.70 낮아 **한쪽에만 벽이 선 비대칭**이었다.
//  ★지우기 전 봉인 차분 실측: 레이크만 판 높이로 낮춤 → **Δ 0**. 대조군으로 +z 볼벽을 통째로 없애면
//   +538이 나오므로 프로브는 볼벽을 보고 있다 = 판 위로 솟은 1.40은 **봉인에 기여가 없다.**
//   ★75 넓은 계단 매스가 관을 채워 그 위를 이미 덮기 때문이다(★74 시점엔 위가 허공 판 35장이었다).
export const CHEEK_TOP_PZ_HI = U_KNEE_END * H + 0.1                         // = 판 윗면(평평) ③≈256.13
export const CHEEK_PZ_RAKE_L = 4.5                                          // 레이크 길이(경사 ≈0.31)
export const CHEEK_PZ_RAKE_X1 = X_LAND_LO                                   // 낮은 끝 = 판 −x변
//  ⚠★75: 하강을 42°로 세우면서 방·볼벽이 동쪽으로 왔다(RM_X1 177.66 → 180.93). 레이크가 상수 길이면
//   벽 밖으로 삐져나간다(검사 [488] 적발). 벽이 실제로 있는 만큼만 쓴다 — 길이는 상한이지 고정값이 아니다.
export const CHEEK_PZ_RAKE_X0 = X_LAND_LO - Math.min(CHEEK_PZ_RAKE_L, Math.max(0.3, X_LAND_LO - (X_DESC_END - 0.1) - 0.1))   // ③ RM_X1과 같은 식(선언 순서상 사본 불가피 — 한 줄 위 주석이 정본)
// 아치 CSG 커터(탐험 리브 2차 컷, 축정렬 상자) — ★'필요 포락선'으로 최소화(검증 ㉙에서 넓은 컷의
//  상단·+z 코너로 시선 누출 실측 → 축소). 필요 = 보행자 몸통(발−0.3~머리+0.4)이 벽면과 겹치는 대각 띠:
//  발 교차 x≈181.3(y 252.7)·머리 교차 x≈180.3(y 253.3) → 벽 제거 필수 대역 x∈[179.9,181.7]·y∈[251.8,254.2].
//  아래 컷은 그 대역에 사방 ~1의 여유를 더한 값(수식 앵커 = X_DESC0). 이보다 키우면 누출 재발 주의.
//  ⚠★75: 리브 구멍(ARCH_*)은 리브 **살 두께**의 파생이 됐으므로 `RIB_WALL_*` 선언 뒤로 옮겼다(TDZ).
//   정의는 이 파일 아래쪽 '★75-f 리브 구멍' 블록에 있다.

// ════════ ★75 넓은 상승 계단 + 중앙 아치 (2026.07.26 · 현도 스케치 `갈림길_스케치.jpg`) ════════
//  구 전망 램프(폭 2 = 관이 허용하는 11.4의 **17%**)를 관 폭을 채우는 계단으로 교체한다.
//  ★논증: 갈림이 좌우에서 **위·아래**로 바뀐다. 크고 당당한 계단이 막다름(1p8)이고,
//   갈 길은 그 바닥에 뚫린 문이다 — 하강이 아치로 들어가 계단 밑을 터널로 지나간다.
//
//  ★★시작점이 이 조형의 유일한 자유도다 — **경사는 판 쪽에서 못 고친다.**
//   실측(2026.07.26): 반원 판을 −x로 물리거나 낮추면 **판이 관 밖으로 나간다**(리브는 물러나는 것보다
//   빨리 솟으므로 두 조작이 같은 방향으로 판을 축에서 민다: DX−4 → 0.83 돌출 · 40°까지 낮추면 1.86).
//   판을 관 축 위에 두고 높이만 훑으면 **경사에 바닥이 있다 ≈ 51°** — 위로도 아래로도 다시 가팔라진다.
//   관 안에서 얻는 최소는 44.4°인데 대가가 1p8 도달 높이 12.15 → 4.96이다(6.4° 벌자고 60%를 버림).
//   → **51°는 튜닝 실패가 아니라 리브의 형태다.** 그래서 주행을 반대편 끝(시작점)에서 번다.
//  ⚠대가 = 브리프 ④("시작 = 판 −x변, 판 자체가 여유")의 평지를 계단이 먹는다. 현도 판정: **0.5(=187.51)**.
//   덤: 계단이 하강 시작 위로 올라가 **터널 머리 여유가 0 → 2.5로 늘어난다**(브리프안은 −1.37 = 터널 불가였다).
export const WSTAIR_ON      = true
//  ⚠`WSTAIR_START_F`·`WSTAIR_X0`·`WARCH_CLEAR`·`WARCH_HEAD`는 **하강 블록 앞**에 있다(하강이 소비).
export const WSTAIR_X1 = rOf(U_LOOKOUT_END) + LK_DISC_DX                        // 맨 위(서·높음) = 반원 판 지름변 ③≈174.62
export const WSTAIR_Y0 = U_KNEE_END * H + 0.1                                   // = 정션 판 윗면(JCT_PLATE_TOP과 같은 식 — 사본 아님)
export const WSTAIR_Y1 = U_LOOKOUT_END * H + LK_DISC_LIFT + LK_DISC_DY          // = 반원 판 윗면(Lookout과 같은 식)
export const WSTAIR_RUN  = WSTAIR_X0 - WSTAIR_X1                                // ③≈12.88
export const WSTAIR_RISE = WSTAIR_Y1 - WSTAIR_Y0                                // ③≈12.15
//  ★규격은 **블롱델부터 재유도**한다(★66 전례 — `STEP_RISE` 0.35는 폐기된 기하의 유산이라 안 쓴다).
//   2R+G = (2·RISE + RUN)/N 을 석조 통례 0.60~0.68의 한가운데(0.64)에 맞춰 N을 정한다.
//   ③에서 N 53 · R 0.229 · G 0.187 · **2R+G = 0.645** ✅
//  ⚠디딤 0.187은 얕다 — 그게 50.85°의 정직한 대가다. 경사를 낮출 수 없다는 것은 실측이 못 박았다:
//   반원 판은 관 안에 있어야 하고, 리브는 물러나는 것보다 빨리 솟으므로 판을 −x로 물리거나 낮추면
//   관 밖으로 나간다(DX−4 → 0.83 · 40°까지 낮춤 → 1.86 돌출). 관 축 위에서 훑으면 **경사에 바닥 ≈51°**.
//  ⚠참(landing)도 못 넣는다: 참은 평균 경사가 flight보다 완만할 때만 서는데(★66) 평균이 이미 50.85°다.
//   → 53단 연속 = **신전 앞 긴 계단 어법**(DESIGN이 '현도 판정 사항'으로 열어 둔 것) · 스케치의 '큰 계단 하나'와 합치.
//  ★★그래서 이 구간의 논증이 이렇게 읽힌다: **막다름(1p8)으로 가는 계단은 가파르고,
//   갈 길(하강)은 완만하다.** ★75 이전에는 정확히 그 반대였다(상승 램프 50.9° · 하강 49°).
export const WSTAIR_N = Math.max(8, Math.round((2 * WSTAIR_RISE + WSTAIR_RUN) / 0.64))   // ③에서 53
export const WSTAIR_R = WSTAIR_RISE / WSTAIR_N                                  // 실제 단높이 ③≈0.229
export const WSTAIR_G = WSTAIR_RUN / WSTAIR_N                                   // 실제 디딤 ③≈0.187
export const WSTAIR_BODY_D = KW_BODY_D                                          // 1.60
//  폭: ★72 수법 그대로 — z 반폭을 상수가 아니라 **관의 함수**로. 융착은 판과 같은 값.
export const WSTAIR_FUSE = JCT_PLATE_FUSE
export const WSTAIR_SEG  = 48                                                   // 윤곽 표본
// ── 중앙 아치(계단 맨 아래 · z=0) ──
//  폭 = 하강 채널(2×PASS_HW = 4.6)에 정합 — 문틀이 통로와 같은 치수(현도 확정 2026.07.26).
//  ⚠자르개는 **딱 필요한 범위만**(★64-5: 넘치면 관벽이 유령 구조로 남는다) → x·y 모두 하강 보행선의 함수.
export const WARCH_ON   = true
export const WARCH_HW   = PASS_HW          // 2.3 (폭 4.6 = 하강 채널 정합, 현도 확정)
export const WARCH_FUSE = 0.10             // 옆 융착(살 0.22보다 얇음)
//  ★75-k 하강 계단우물(슬롯)은 볼트보다 **넉넉히** 넓어야 한다(2026.07.26 현도: "갈림판 쪽,
//   출구 반대편에서 약간 튀어나온다"). ⛔슬롯 반폭과 볼트 반폭이 **정확히 같아서**(둘 다 1.80)
//   정션 판·매듭이 볼트 벽면에 두께 0.04짜리 **날개**로 남았다 — 스치는 각도에서 그게 튀어나와 보인다.
//   ⚠같은 값 = 동일 평면이기도 하다(z-fighting의 재발) — 오늘 디딤판에서 겪은 것과 같은 병.
export const JCT_SLOT_MARGIN = 0.20        // 볼트보다 더 넓어야 하는 부재들의 여유
// ════════ ★75-l **폭 사슬** — 같은 병이 하루에 네 번 났다 ════════
//  ⛔재발 이력(2026.07.26, 전부 "두 값이 정확히 같아서" 생겼다):
//   ① 하강 디딤판 반폭 1.70 = 볼벽 안쪽 면 1.70 → z-fighting("우글우글")
//   ② 계단우물 반폭 1.80 = 볼트 반폭 1.80 → 정션 판·매듭이 볼트 안에 두께 0.04 날개
//   ③ 쪼개진 계단 디딤판 안쪽 모서리 1.80 = 볼트 반폭 1.80 → 두께 0.20 날개(현도가 본 그것)
//   ④ (구현 중) 아치 자르개 좌표가 벽과 어긋나 감산이 무효
//  ★근본 원인은 **폭을 정하는 값이 여러 곳에서 따로 계산된 것**이다. 한 줄로 묶는다.
//   규칙: 채널 < 볼트 < 여유 — 셋은 **단조 증가**해야 하고, 검사가 그걸 강제한다.
export const CHANNEL_HW = PASS_HW                          // ① 몸이 지나는 폭(볼벽 안쪽 면)
export const VAULT_HW   = CHANNEL_HW + WARCH_FUSE          // ② 볼트(아치)가 파는 폭 — 채널보다 살짝 넓다
export const CLEAR_HW   = VAULT_HW + JCT_SLOT_MARGIN       // ③ **볼트 안에 남으면 안 되는 부재**가 물러설 폭
//  ⚠새 부재를 이 권역에 놓을 때: 걷는 면이면 CHANNEL_HW, 파는 것이면 VAULT_HW,
//   "볼트 안에 보이면 안 되는 것"이면 CLEAR_HW. 그 셋 밖의 숫자를 새로 쓰지 말 것.
export const WARCH_DROP = 0.45             // 아치 밑변을 하강 보행선보다 이만큼 아래로(문턱 틈 방지 융착)
//  ★★2026.07.26 현도 소견 2회: "정면에서 봤을 때 아래가 아치형으로 뚫린 모습"이 안 나온다.
//   실측 입면으로 원인 확정 — **아치 크라운이 254.2 = 판 윗면 256.13보다 1.9 아래**였다.
//   ⛔내 잘못: "발치에서 하강이 FOOT_DROP 내려가 있어야 한다"를 아치 크라운에까지 적용했다.
//    계단이 바닥에서 솟는 한 그 발치 밑 구멍은 **구조적으로 언제나 바닥보다 낮다** → 판 위에서 안 보인다.
//   ★현도가 그린 것은 다른 것이다: 계단 **아랫부분 중앙을 잘라내** 아치가 판 위로 솟는 것.
//    첫 단 십수 개가 좌우로 갈라지고 그 사이가 아치 공동이 된다(기단을 뚫은 신전 계단 어법).
//    자르개 크라운을 판 위 `WARCH_RISE_ABOVE`까지 **들어올려** 첫 단들을 실제로 깎아낸다.
export const WARCH_RISE_ABOVE = 3.0   // ★판 윗면 위로 아치가 솟는 높이 = 정면에서 읽히는 크기(2026.07.26 현도: 더 높게)
                                      //  ⚠이걸 키우면 `WARCH_H_MAX`도 같이 키워야 한다 —
                                      //   1차에서 2.2로 올렸는데 실제 병목은 H_MAX 5.6이라 크라운이 안 올라갔다.
