//  근거 = **이 권역은 회전 대칭**이다(리브 72 동형 · 상부 회전 −10° = 리브 간격 5°의 정확히 2배라
//  격자가 자기 위로 겹침). 회랑은 CL_PHI0·CL_PHI1의 순수 함수이고 웨이포인트·등불이 뒤따르므로
