// ★79(2026.07.28): 48.6° → **47.4°**. 등불 방(RM10_*, 아래)이 회랑 끝에 붙으면서 끝캡이 방 벽을 만나는
//  자리로 당겨졌다. 47.4는 리브 #9(45°)에서 2.40°·#10(50°)에서 2.60° — 살 각반폭 2.02°를 양쪽 다 비껴간다
//  (★78 튜닝 규칙의 취지 = 리브 중심선과 공면 금지. '5의 배수 −1.4'는 그 규칙의 한 해였을 뿐 규칙 자체가 아니다).
