export const LAMP_POOL_R   = 1.7                   // 바닥 빛 웅덩이 반지름(코어 0.55배 + 헤일로)

// ══ ★★★78-2 회랑 계단 바닥 (2026.07.28 현도 스케치) ═════════════════════════════
//  "걸으면서 회랑 층고를 계속 확장한다. 천장을 올리는 게 아니라 **바닥을 내린다**."
//  등불 발치 = 수평 층계참 / 등불 사이 = 짧은 하강 계단. 층고 20 → 29.6, 창 5.4 → 15.0.
//
//  ★왜 바닥인가(현도 의도): 천장을 올리면 리브가 매달린 절대 높이(LAMP_ENTRY_Y 263.4)와 어긋난다.
//   바닥을 내리면 리브·지붕은 그대로 있고 **몸만 가라앉는다** — 걸을수록 위가 커지는 체험.
//
//  ⚠**PASS_FLOOR_Y는 못 건드린다.** 하강 채널·전실 방·갈림 판이 전부 그 값을 읽는다.
//   회랑만 그 아래로 내려가고, 도착점(테라스)이 따라 내려온다.
export const CL_SEG_DROP  = 1.2                       // ★현도: 등불 한 구간당 하강
export const CL_STEP_N    = 5                         // ★현도: 구간당 단수
export const CL_STEP_RISE = CL_SEG_DROP / CL_STEP_N   // 단높이 0.24 (파생 — 둘을 곱으로 묶는다)
//  ★단너비는 짓지 않고 **무릎길 경사를 물려받는다**(여정 계단 어휘가 둘로 갈리는 것 방지).
//   KW 0.19/0.22 = 40.8° → 같은 경사에서 단높이 0.24의 단너비.
//  ★★78-3(2026.07.28 현도 "계단이 약간 짧게 느껴지네"): **단수로는 못 늘린다.**
//   계단 길이 = N·go = N·(SEG_DROP/N)·(go/rise) = **SEG_DROP / tan(경사)** — N이 약분돼 사라진다.
//   단수를 늘리면 단높이만 잘게 쪼개지고 길이는 그대로다. 길게 하는 길은 둘뿐:
//   ⓐ 경사를 눕힌다(하강 유지) ⓑ 구간 하강을 키운다(경사 유지 — 그건 CL_SEG_DROP).
//   실측표(하강 1.2 기준): 40.82°→1.39 · 35°→1.71 · **30°→2.08(1.5배)** · 25°→2.57 · 20°→3.30
//   층계참 : 계단 비율 = 1:9.7 → 1:7.7 → **1:6.1** → 1:4.8 → 1:3.5
//  ⇒ 현도 "약간"으로 30° 채택. 무릎길 40.82°에서 처음 갈라진 값이라 **의도적 이탈임을 여기 적어 둔다**
//   (K3는 어휘 동일 대신 프로젝트 계단 대역 [20°,45°] 안인지로 재고 두 값을 나란히 보고한다).
export const CL_STEP_SLOPE_DEG = 30
export const CL_STEP_GO   = CL_STEP_RISE / Math.tan(CL_STEP_SLOPE_DEG * Math.PI / 180)   // ≈0.416
export const CL_STEP_RUN  = CL_STEP_N * CL_STEP_GO             // 계단 길이 ≈2.08
export const CL_STEP_DPHI = CL_STEP_GO / CL_R                  // 한 단의 각너비
export const CL_LAMP_PHI  = LAMP_RIBS.map((k) => k * 2 * Math.PI / MERIDIANS)
//  계단은 등불과 등불의 **중점**에 선다 → 층계참이 등불 좌우로 대칭(각 ±(5°−CL_STEP_RUN/CL_R)/2, 호 ≈6.7).
export const CL_STAIR_MID = CL_LAMP_PHI.slice(0, -1).map((p, i) => (p + CL_LAMP_PHI[i + 1]) / 2)
export const CL_STAIR_HPHI = CL_STEP_RUN / 2 / CL_R
export const CL_DROP_TOTAL = CL_SEG_DROP * CL_STAIR_MID.length      // 8구간 → 9.6
export const CL_FLOOR_END  = PASS_FLOOR_Y - CL_DROP_TOTAL           // ③≈238.43 = 마지막 층계참·스텁·테라스
//  ★지붕·창 위턱은 **절대 높이로 전환**. 구판은 바닥 상대(floor+CL_ROOF)라 바닥이 내려가면 천장이 따라 내려갔다 —
//   그건 현도 의도("천장은 그대로")의 정반대다. 시작 지점에서는 구값과 항등(PASS_FLOOR_Y+CL_ROOF).
export const CL_ROOF_Y     = PASS_FLOOR_Y + CL_ROOF                 // ③≈268.03 고정
export const CL_HEAD_Y     = PASS_FLOOR_Y + CL_HEAD                 // ③≈255.03 고정(창 위턱)
export const CL_WALL_BOT   = CL_FLOOR_END - PASS_T                  // 벽 밑단 = 최저 바닥 아래
export const clLandingY = (j) => PASS_FLOOR_Y - CL_SEG_DROP * j     // j번째 층계참 높이(j=0..8)
//  바닥: 층계참은 평평, 계단 위는 **디딤판 이산**(연속 경사가 아니다 — 실제 기하와 같은 함수를 검사도 쓴다).
export function clFloorY(phi) {
  let y = PASS_FLOOR_Y
  for (let i = 0; i < CL_STAIR_MID.length; i++) {
    const s0 = CL_STAIR_MID[i] - CL_STAIR_HPHI, s1 = CL_STAIR_MID[i] + CL_STAIR_HPHI
    if (phi >= s1) y -= CL_SEG_DROP
    else if (phi > s0) y -= CL_STEP_RISE * Math.min(CL_STEP_N, Math.floor((phi - s0) / CL_STEP_DPHI) + 1)
  }
  return y
}
//  ★★파라펫(창턱)은 계단 **밑에서** 내려간다 — 중간에서 내리면 계단 하반부에서 국소 바닥 위 1.0이 되어
//   눈높이 1.6보다 0.6 낮아진다 = 그 구간만 아래 세계가 열린다(_probe_cloister78이 잡은 결함).
//   계단 내내 윗 층계참 창턱을 유지 → 파라펫 1.6~2.8, 절대 1.6 밑으로 안 감(하향 시선 차단 구조 보존).
// ── ★★78-4 회랑 벽 두께(2026.07.28 현도 "양옆 벽에 두께가 없어서 계단이 삐져나온다") ──────
//  ⚠이건 신기능이 아니라 **결함 수리**다. 회랑 벽은 두께 0 셸(r=rIn·rOut)이었고, 바닥 링·챌판은
//   원래부터 양쪽으로 PASS_T(0.6)씩 더 뻗어 있었다. 평바닥일 땐 가장자리 한 줄이라 안 보였는데,
//   ★78-2로 조각이 89장(디딤판 40·층계참 9·챌판 40)이 되자 전부 벽 밖으로 튀어나와 드러났다.
//   → 벽에 살을 주면 그 0.6이 **물림**으로 뒤집힌다. 바닥 쪽은 손댈 게 없다(DESIGN §9 '두께 0 면' 해소).
//  ★덤 = 현도가 짚은 대로 창에 **인방 깊이**가 생긴다(★77 프리즈 창의 어휘 — 종이에 낸 구멍이 아니라 개구).
//  대역: 하한 = 바닥 물림 0.6 + 여유 → **T > 0.9**. 상한 = 창 위턱(255.03)에서 리브 살까지 3.49이므로
//   여유 1.0을 남기면 **T ≤ 2.5**(그 위로는 창밖 리브가 인방에 닿을 듯이 붙는다).
//   그 밖의 상한은 느슨하다(안벽: 스텁 길이 8.9 · 테라스 외림까지 9.0).
//  ⚠상단(y≳260)에서는 벽 두께와 무관하게 리브가 이미 회랑을 관통한다(등불 진입고 263.4 = 체제 b).
//   두께가 그걸 새로 만들지 않는다 — 다만 리브가 두꺼운 살에서 나오게 된다.
export const CL_WALL_T = 1.5               // ★노브 — 대역 [0.9, 2.5]. 현도 육안 판정 대상
export const CL_R_IN2  = CL_R - CL_HW - CL_WALL_T   // 안벽 안쪽면 ③≈165.9
export const CL_R_OUT2 = CL_R + CL_HW + CL_WALL_T   // 바깥벽 바깥면 ③≈174.1
//  바닥·챌판이 벽 살 속으로 무는 깊이(구 '오버행'의 재해석 — 값은 안 바뀐다).
//  ★75 폭 사슬: 물림 < 두께여야 어느 면과도 공면이 아니다. 0이면 z파이팅, 두께 이상이면 관통.
export const CL_FLOOR_BITE = PASS_T        // 0.6

// ── ★★78-3 창턱 두 어법(현도 "버젼 두가지 만들어서 로컬에서 판정") ────────────────────
//  'step'  = 계단식 — 창턱이 층계참마다 한 칸씩 내려간다(★78-2 구현분).
//  'slope' = 경사진 직선 — 창턱이 시작→끝을 잇는 한 줄로 내려간다(원통 위라 실제로는 나선).
//  ⚠**직선은 그냥 그으면 불변식이 무너진다.** 끝점(시작 바닥 → 끝 바닥)을 잇는 순수 직선은
//   첫 계단 직전(φ≈7.3°)에서 파라펫이 **0.477**까지 내려간다 — 눈높이 1.6에 1.123 모자라고,
//   그 구간만 아래 세계가 열린다. 바닥은 계단인데 선은 균일하게 내려가므로 **계단 직전이 항상 최악**이다.
//   → 직선을 **최저점이 정확히 CL_SILL이 되도록 들어올린다**(들림값은 상수가 아니라 파생 — 바닥이 바뀌면 따라온다).
//   대가: 창이 전 구간 그만큼 낮아진다(시작 창높이 5.4 → 4.28). 이게 두 어법의 실질 차이다.
export const CL_WIN_MODE = 'step'          // ★현도 판정 대기 — 'step' | 'slope'
const clSlopeBase = (phi) => PASS_FLOOR_Y + (CL_FLOOR_END - PASS_FLOOR_Y) * (phi - CL_PHI0) / (CL_PHI1 - CL_PHI0)
//  ⚠들림값을 **표본으로 구하면 안 된다.** 8000점으로 뽑았더니 20000점으로 재는 검사가 더 낮은 점을
//   찾아 실패했다(2026.07.28 실제 적발). 최저점은 해석적으로 정해져 있다 —
//   바닥은 계단(구간마다 상수)이고 선은 단조 감소하므로, **각 평평 조각의 오른쪽 끝**이 그 조각의 최저점이다.
//   그 유한집합의 min이 정확한 답이다. 표본 밀도와 무관해진다.
export const CL_WIN_SLOPE_LIFT = (() => {
  let worst = Infinity
  for (const g of clFloorSegments().segs) worst = Math.min(worst, clSlopeBase(g.p1) - g.y)
  return CL_SILL - worst                                        // ③≈2.723
})()
export const clSillSlopeY = (phi) => clSlopeBase(phi) + CL_WIN_SLOPE_LIFT
//  활성 어법의 창턱(둘 중 무엇을 켜든 검사·프로브가 같은 함수를 본다)
export const clSillActiveY = (phi) => (CL_WIN_MODE === 'slope' ? clSillSlopeY(phi) : clSillY(phi))

//  ★★정본은 이 두 함수다 — Dome.jsx가 그리는 조각도, 검사가 재는 조각도 여기서 나온다.
//   구판처럼 컴포넌트 안에서 루프를 돌리면 검사가 그 루프를 **다시 적어야** 하고, 두 벌은 반드시 어긋난다.
//   clFloorY(해석식)는 이것과 독립된 두 번째 표현이며, 둘의 일치를 check_corridor K3가 상시 대조한다.
export function clFloorSegments() {
  const segs = [], risers = []
  let cur = CL_PHI0
  for (let i = 0; i < CL_STAIR_MID.length; i++) {
    const s0 = CL_STAIR_MID[i] - CL_STAIR_HPHI, top = clLandingY(i)
    segs.push({ p0: cur, p1: s0, y: top, kind: 'landing', i })          // 층계참(등불 발치)
    for (let n = 0; n < CL_STEP_N; n++) {                               // 짧은 하강 계단
      const a0 = s0 + n * CL_STEP_DPHI
      segs.push({ p0: a0, p1: a0 + CL_STEP_DPHI, y: top - CL_STEP_RISE * (n + 1), kind: 'tread', i, n })
      risers.push({ phi: a0, top: top - CL_STEP_RISE * n })
    }
    cur = s0 + CL_STEP_N * CL_STEP_DPHI
  }
  segs.push({ p0: cur, p1: CL_PHI1, y: clLandingY(CL_STAIR_MID.length), kind: 'landing', i: CL_STAIR_MID.length })
  return { segs, risers }
}
//  파라펫 띠(개구 구간으로 잘라 낸다) — 계단 **밑**에서 한 칸 강하.
export function clSillBands() {
  const out = []
  let c = CL_PHI0
  for (let i = 0; i <= CL_STAIR_MID.length; i++) {
    const end = i < CL_STAIR_MID.length ? CL_STAIR_MID[i] + CL_STAIR_HPHI : CL_PHI1
    const p0 = Math.max(c, CL_OP_P0), p1 = Math.min(end, CL_OP_P1)
    if (p1 > p0) out.push({ p0, p1, y: clLandingY(i) + CL_SILL })
    c = end
  }
  return out
}
export function clSillY(phi) {
  let y = PASS_FLOOR_Y
  for (let i = 0; i < CL_STAIR_MID.length; i++) if (phi >= CL_STAIR_MID[i] + CL_STAIR_HPHI) y -= CL_SEG_DROP
  return y + CL_SILL
}

// ── 테라스(중앙, 도착) (반지름 ×SCALE · y는 통로에서 파생 — 자유 요소의 접속 해소) ──
// ★78-2: PASS_FLOOR_Y → **CL_FLOOR_END**. 회랑이 걸으며 9.6 내려가므로 도착점도 같이 내려온다
//  (현도 ⓐ "테라스도 같이 그냥 내리면 돼"). '문턱 없는 도착' 문법은 **관계가 보존**된다 — 값만 옮겨간다.
//  ⛔★79-5(2026.07.28 현도 "되돌아갈 필요 없지, 테라스를 내리면 되니까"): **회랑 파생 폐기.**
//   등불 방이 회랑의 종점이 됐으므로 '문턱 없는 도착'의 상대는 회랑이 아니라 **방의 출구 통로**다.
//   관계는 그대로 보존되고 값만 12 내려간다(238.43 → 226.43) — ★78-2가 9.6 내렸을 때와 같은 수법.
//   ★부수 이득: 테라스 눈높이 240.0 → 228.0이라 정점 렌즈를 **32.0° → 35.3°**로 더 크게 올려다본다.
//   정의는 방 블록 뒤(RM10_FLOOR_Y 필요) — 아래 ★79-5 절.

// ── ★79 등불 방(1p10의 집) — 2026.07.28 현도 스케치 ──────────────────────────────────
//  회랑 끝에 **붙여** 짓는 원통 방. 중앙에 열 번째 등불이 서고 그 관이 리브 #10 밑면에 꽂힌다.
//  현도: *"천체망원경을 바라보는 그런 공간. 둥근 방, 중앙에 바로 위를 올려다보는 등불,
//   등불이 속성에서 바로 추출되어 나오는 게 잘 보이도록 층고를 높게."*
//
//  ★★왜 하강로가 **방 안 벽을 따라 도는가** — 선택이 아니라 유도다(실측 2026.07.28):
//   회랑 계단 어법(단높이 0.24 · 30°)으로 RM10_DROP을 내려가려면 수평 run = DROP×√3 이 필요하다(12 → 20.78).
//   그런데 '붙여 짓는다' = 방과 회랑 끝이 **겹친다**는 뜻이라 그 사이에 곧은 하강로가 들어갈 자리가 **0**이다.
//   방을 밖으로 밀어 자리를 만들면 등불이 리브 방위(5°의 배수)를 벗어나 리브 밑에 못 선다.
//   ⇒ 남는 해는 하나뿐: 하강로가 방 안에 있다.
//
//  ★★왜 회랑에서 방이 안 보이는가(현도 의도 = 호기심) — 바닥을 내리는 것으로 산다:
//   눈높이 1.6에서 문턱(CL_FLOOR_END)을 넘겨다보면, 방 바닥이 보이기 시작하는 거리는 1.6×(먼벽거리)/DROP 이다.
//   DROP 12 · ρ 7.3이면 **끝캡 1.4 앞**까지 와야 안이 보인다. 등불 갓 입(바닥+2.7)도 같은 논리로 가려진다.
//   ⇒ 층고를 올리는 게 아니라 바닥을 내린다 — ★78-2 회랑과 같은 어법.
//
//  ★★천장은 대부분 리브다. RM10_ROOF_Y > LAMP_ENTRY_Y(263.4)면 리브 #10이 천장을 관통한다.
//   구멍의 **마개는 리브 자신**이라 하늘 누출이 없다(★71 빛 기둥과 같은 봉인 논리). 리브는 한 톨도 안 건드린다 —
//   뚫리는 것은 천장이다(LOCKED 예외 아님).
//  ⚠스포 상한: 이웃 리브 #9·#11은 천장을 아무리 올려도 방 축에서 **8.8** 아래로 안 내려온다(수렴값).
//   따라서 RM10_RHO ≤ 8.8이면 방 안에 보이는 리브는 #10 하나뿐 = 1p11 반전 무손상. 검사가 강제한다.
export const RM10_ON      = true
export const RM10_K       = 10                                  // 리브 방위 #10 = 50°
export const RM10_PHI     = (RM10_K / MERIDIANS) * Math.PI * 2
export const RM10_AX_R    = CL_R                                // 방 축 반경 = 회랑 중심선 = 등불이 서는 자리
export const RM10_RHO     = 8.4                                 // ★노브 안쪽 반지름 — 상한 8.8(스포)·하한은 계단폭+빈바닥
export const RM10_WALL_T  = CL_WALL_T                           // 벽 두께 = 회랑 어법(1.5)
export const RM10_DROP    = 12.0                                // ★노브 하강 = 봉인 깊이 = 층고 증가분
export const RM10_FLOOR_Y = CL_FLOOR_END - RM10_DROP            // ③≈226.43
export const RM10_ROOF_Y  = 282                                 // ★노브 천장 — 리브가 기울어 내려오는 구간의 끝(위는 곧은 수직)
export const RM10_STAIR_W = 3.0                                 // 계단 폭 — ★79-3에서 2.6→3.0(원뿔 경사가 머리 쪽 폭을 먹는다, 아래 유효폭)
// ── ★79-3 원뿔대(2026.07.28 현도: "아래로 갈수록 넓어지면 바닥을 키울 수 있지 않나") ──────────
//  ★★원뿔이 **어디서부터** 벌어질 수 있는지는 선택이 아니다 — 실측이 한 높이로 못 박는다:
//   높이별 방 반지름 상한 = y282 **8.82**(이웃 리브) · y250 27.4 · **y238.43 11.60** · y226 90.3.
//   238.43 한 높이에서만 테라스 판이 목을 조른다(방 축 r170 − 테라스 바깥테 r158.4 = 11.60이고,
//   방 방위 50°가 테라스 부채꼴 ±68.8° 안이라 방위상 테라스 **바로 위**다). 넘으면 방 벽이 테라스를 뚫고 올라온다.
//   게다가 그 높이가 하필 ⓐ 문턱·층계참 ⓑ 회랑 스나우트가 닿는 자리(끝캡 최원 8.29)다 — 벽이 거기서
//   밖으로 도망가면 회랑 주둥이가 허공에 뜬다.
//  ⇒ **층계참 위 = 원기둥(ρ) · 아래 = 원뿔.** 마침 그 아래가 정확히 계단 구간(12)이라 벌어지는 구간 = 내려가는 구간.
//  ★★유효폭(현도: "옆면에 사람에게 닿지 않도록"): 벽이 위로 갈수록 안으로 기우니 **발밑 폭 ≠ 걸을 수 있는 폭**이다.
//   머리 높이에서 벽이 RM10_HEADROOM×tanα 만큼 들어와 있다 ⇒ 유효폭 = 폭 − 헤드룸×tanα. 검사가 강제한다.
export const RM10_CONE_DEG  = 25                                // ★노브 원뿔 반각(수직 기준). 0 = 구 원기둥
export const RM10_CONE_K    = Math.tan(RM10_CONE_DEG * Math.PI / 180)
export const RM10_HEADROOM  = 2.2                               // 유효폭을 재는 기준 높이(사람 + 여유)
export const RM10_STAIR_USABLE = RM10_STAIR_W - RM10_HEADROOM * RM10_CONE_K   // 실제로 걸을 수 있는 띠
export const RM10_CCW     = true                                // 도는 방향
export const RM10_DOOR_H  = PASS_DOOR_H                         // 입구 인방 높이 — 문 어법 계승(4.6). 이게 회랑 쪽 봉인의 윗뚜껑
//  파생 — 방 로컬 극좌표(원점 = 축, θ는 +x(반경 바깥)에서 +z(회랑 진행) 쪽으로)
export const RM10_CONE_Y   = CL_FLOOR_END                       // ★원뿔 시작 = 층계참 = 테라스 판 = 스나우트 접점(셋이 같은 높이인 것이 이 형태의 이유다)
export const rm10R         = (y) => RM10_RHO + Math.max(0, RM10_CONE_Y - y) * RM10_CONE_K   // 그 높이의 벽 안쪽 반지름
export const RM10_FLOOR_R  = rm10R(RM10_FLOOR_Y)                // 바닥 반지름(25°·12 → 14.0)
export const RM10_ENTRY_TH = -Math.PI / 2                       // 입구 = 회랑이 들어오는 쪽 = 로컬 −z
export const RM10_STEP_N   = Math.round(RM10_DROP / CL_STEP_RISE)          // 50단
export const RM10_DOOR_HTH = Math.asin(CL_HW / RM10_RHO)                   // 입구 각반폭(통행폭 5.2 기준 — 문은 원기둥 구간에 있다)
export const RM10_FLOOR_OPEN_R = RM10_FLOOR_R - RM10_STAIR_W               // **바닥**에서 계단이 안 덮는 반경(원뿔 기준) 11.0
//  ⚠★79-4 이름을 갈랐다(현도 적발 "계단 초입에 발 밟을 판이 없다"의 근본 원인):
//   ★79-3에서 이 값의 **의미가 바뀌었는데**(천장 기준 → 바닥 기준) 층계참이 옛 의미로 계속 쓰고 있었다.
//   층계참은 원기둥 구간에 있으므로 11.0을 쓰면 안쪽 > 바깥쪽이 되어 **역전된 링 = 아무것도 안 그려진다.**
//   한 이름이 두 뜻을 가지면 반드시 한쪽만 고쳐진다 — ★78 '두 벌로 적힌 규칙' 교훈의 변종.
export const RM10_LAND_RIN   = RM10_RHO - RM10_STAIR_W                     // **층계참** 안쪽 반지름(원기둥 기준) 5.4
//  ⚠★79-4 층계참 높이 = 회랑 바닥보다 0.02 **아래**(현도 적발 "판들이 겹쳐 우글우글"):
//   회랑 스나우트가 방 안으로 1.28 물려 있어 두 바닥이 폭 2.78의 띠에서 겹치는데, 구판은 둘 다
//   `CL_FLOOR_END − 0.02`로 **완전 공면**이었다 = z-파이팅. 방·회랑 이음매의 기존 규약(0.02 낮춰 덮이게)을 따른다.
export const RM10_LAND_Y     = CL_FLOOR_END - 0.04                         // 회랑 바닥(−0.02)이 위에서 덮는다. 단차 0.02 = 무시 가능
// ── ★79-3 바닥 = 동심원 여러 겹. **두 어법을 다 짓고 스위치로 비교한다**(현도 요청) ──
//  'bowl' = 아래로 파임(중앙 최저) — 현도 원안. 'peak' = 위로 쌓음(중앙 최고) — 드럼 바닥 TIER_PROFILE과 같은 방향.
//  어휘 출처 = 드럼 바닥 `TIER_*`(7겹·단높이 0.7·중앙 높음). 단높이는 STEP_UP 0.8 안이라 **오르내림이 된다**.
//  ⚠꺼진 어법도 검사가 상시 잰다(★78-3 M절 전례) — 안 그러면 한쪽만 썩는다.
export const RM10_FLOOR_MODE = 'bowl'                           // ★노브 'bowl' | 'peak'
export const RM10_TIER_N     = 6                                // 겹 수(= 단차 5개)
export const RM10_TIER_RISE  = 0.6                              // 겹당 높이차 — STEP_UP 0.8 안
export const RM10_TIER_SIGN  = (RM10_FLOOR_MODE === 'peak' ? 1 : -1)
export const RM10_CENTER_Y   = RM10_FLOOR_Y + RM10_TIER_SIGN * (RM10_TIER_N - 1) * RM10_TIER_RISE  // 중앙(등불 발치) 높이
export const RM10_BOT_Y      = Math.min(RM10_FLOOR_Y, RM10_CENTER_Y) - PASS_T                      // 바닥 매스 밑면
//  ★생성 규칙은 컴포넌트가 아니라 상수에 둔다(★78 교훈) — Dome이 그리는 것과 검사가 재는 것이 한 출처.
export function rm10Steps() {
  //  ⚠원뿔이라 **한 단의 각폭이 단마다 다르다**(반경이 커질수록 좁아진다) → 누적으로 돌린다.
  const s = RM10_CCW ? 1 : -1, out = []
  let th = RM10_ENTRY_TH + s * RM10_DOOR_HTH                    // 입구 층계참 끝에서 첫 단이 시작
  for (let i = 0; i < RM10_STEP_N; i++) {
    const top = CL_FLOOR_END - (i + 1) * CL_STEP_RISE           // 그 단을 밟고 난 높이(마지막 = RM10_FLOOR_Y)
    const rOut = rm10R(top), rIn = rOut - RM10_STAIR_W
    const dth = CL_STEP_GO / ((rIn + rOut) / 2)                 // 단너비를 그 반경의 호로 환산
    out.push({ i, thA: th, thB: th + s * dth, top, rIn, rOut })
    th += s * dth
  }
  return out
}
export const RM10_TURN = Math.abs(rm10Steps().at(-1).thB - (RM10_ENTRY_TH + (RM10_CCW ? 1 : -1) * RM10_DOOR_HTH))

// ── ★79-5 테라스 출구 통로(1p11의 집) — 2026.07.28 현도 스케치 ─────────────────────
//  현도: *"방 바닥 부근에 출구, 방 외벽을 따라 약간 회전하는 통로(외부가 보이면 안 됨), 그리고 테라스로.
//   나왔을 때 방향은 돔 중심부, 클라이막스를 목격하는 방향."*
//
//  ★출구 문 방위 θ 90° — 구조 판단(현도 위임):
//   ⓐ 입구 문(θ 270°)의 **정반대**라 통로가 입구·회랑 스나우트와 원리적으로 안 만난다.
//   ⓑ 거기서 돔 중심(θ 180°)까지 **정확히 90° = 4분의 1 바퀴**. 계단과 같은 회전 방향으로 이어진다.
//   ⓒ 통로 바깥벽의 돔 중심 쪽 끝이 곧 **테라스의 새 림**이 된다(TERRACE_ROUT 파생) — 잃는 폭을 통로가 채운다.
//  ★밀폐가 요구다(현도 "외부가 보이면 안 됨"): 개구는 둘뿐 — 방 쪽 문 하나, 테라스 쪽 문 하나.
//   이게 1p11 반전의 마지막 차단막이다(스포 3중 ③ '연결 통로 밀폐'의 계승). 검사가 개구 수를 센다.
//  ★통로 안벽 = 방의 원뿔 바깥면이라 **위로 갈수록 멀어진다**(바닥 폭 3.0 → 천장 폭 5.3).
//   계단과 반대로 헤드룸이 공짜다 — 벽이 사람에게서 물러나는 방향이다.
export const RM10_EXIT_W    = 3.0                                  // 통로 폭(현도 "방 계단과 비슷하게 좁게")
export const RM10_EXIT_ROOF = 5.0                                  // ★노브 통로 내부고(구 스텁 어휘 ST_ROOF 계승)
export const RM10_EXIT_TH   = Math.PI / 2                          // 방 쪽 출구 문 방위(로컬 θ) = 입구의 정반대
export const RM10_TERR_TH   = Math.PI                              // 테라스 쪽 문 방위 = 돔 중심 방향
export const RM10_EXIT_DOOR_W = 3.0                                // 방 쪽 문 폭(통로와 같게)
//  ★79-6(현도): 회전이 끝나자마자 테라스가 아니라, **좌회전 후 직선 구간 몇 걸음**을 지나 나선다.
//   공개 지점이 곡선 끝이 아니라 직선 끝이 되므로, 나서는 방향이 흔들리지 않고 돔 중심으로 못 박힌다.
export const RM10_STR_L      = 8.0                                 // ★노브 직선 구간 길이("몇 걸음")
export const RM10_TERR_DOOR_W = 2.4                                // 테라스 쪽 문 폭(통로 3.0보다 좁게 → 문선 0.3씩)
export function rm10Tiers() {
  //  i=0이 바깥 겹. 바깥 겹 윗면 = RM10_FLOOR_Y(계단이 내려서는 높이)이고 안으로 갈수록 sign만큼 어긋난다.
  //  ⚠★바깥 겹은 **계단 띠와 같은 폭**이다(균등 분할 아님). 균등하게 나눴더니 폭 2.33 < 계단 3.0이라
  //   계단 안쪽 0.66이 둘째 겹 위로 0.6 떠서 걸쳤다 — 프로브 [32]가 잡은 실제 결함(눈으로는 안 보인다).
  //   계단이 내려서는 자리를 한 겹이 통째로 받게 하면 그 겹침이 원리적으로 사라진다.
  const out = [{ i: 0, r0: RM10_FLOOR_OPEN_R, r1: RM10_FLOOR_R, top: RM10_FLOOR_Y }]
  const d = RM10_FLOOR_OPEN_R / (RM10_TIER_N - 1)
  for (let i = 1; i < RM10_TIER_N; i++)
    out.push({ i, r0: RM10_FLOOR_OPEN_R - i * d, r1: RM10_FLOOR_OPEN_R - (i - 1) * d,
               top: RM10_FLOOR_Y + RM10_TIER_SIGN * i * RM10_TIER_RISE })
  return out
}

//  ★79-5 파생 — 통로 띠와 두 문의 각폭
export const RM10_CONE_T    = RM10_WALL_T / Math.cos(RM10_CONE_DEG * Math.PI / 180)  // 기운 면의 **수직** 두께가 t가 되게
export const RM10_EXIT_RIN  = RM10_FLOOR_R + RM10_CONE_T           // 통로 안쪽 = 방 벽 바깥면(바닥 높이) 15.66
export const RM10_EXIT_ROUT = RM10_EXIT_RIN + RM10_EXIT_W          // 통로 바깥면 18.66
export const RM10_EXIT_DHTH = Math.asin(RM10_EXIT_DOOR_W / 2 / RM10_FLOOR_R)         // 방 쪽 문 각반폭(방 벽 반경 기준)
export const RM10_TERR_DHTH = Math.asin(RM10_EXIT_DOOR_W / 2 / RM10_EXIT_ROUT)       // 테라스 쪽 문 각반폭(통로 바깥 반경 기준)
export const RM10_EXIT_TH0  = RM10_EXIT_TH - RM10_EXIT_DHTH - 0.04                   // 통로 시작(방 쪽 문선 바깥 + 여유)
export const RM10_EXIT_TH1  = RM10_TERR_TH + RM10_TERR_DHTH + 0.04                   // 통로 끝(테라스 쪽 문선 바깥 + 여유)
export const RM10_EXIT_FLOOR_Y = RM10_FLOOR_Y                      // 통로 바닥 = 방 바깥 겹 윗면(단차 0)
export const RM10_EXIT_ROOF_Y  = RM10_EXIT_FLOOR_Y + RM10_EXIT_ROOF
// ── ★79-5 테라스 = 출구 통로 파생(구 회랑 파생 폐기) ──────────────────────────────
//  ★높이: 통로 바닥과 **같다** — '문턱 없는 도착' 문법은 상대만 바뀌고 관계는 보존된다.
//  ★바깥 림: 통로 바깥벽에서 PASS_T만큼 **더 나가** 벽 밑으로 물린다(문지방 이음매 봉인 — 틈 금지).
//   ⚠구 33×SCALE(158.4)로 두면 방 원뿔이 이 높이에서 테라스를 **4.05 파고든다**(실측). 파생이 그걸 원천 봉쇄한다.
export const TERRACE_Y    = RM10_EXIT_FLOOR_Y
export const RM10_STR_END = RM10_EXIT_ROUT + RM10_STR_L            // 직선 구간 끝(방 축에서)
export const TERRACE_ROUT = RM10_AX_R - RM10_STR_END + PASS_T

// ══ ★80 출구 통로 = 감아 오르는 나팔 (2026.07.28 현도 스케치 · 5차) ═════════════
//  현도 5차: "통로에 **상승**을 넣고, 방을 따라 회전하는 부분을 **더 회전**시켜서
//   통로의 돔 바깥쪽 벽이 **회랑 외벽에 붙게**. 사선 말고 **정조준**으로 돔 내부를 보게.
//   길이는 받아들이되, 공간 확장을 **후반부에 드라마틱하게**."
//  전체 의도(3차부터 불변): 등불 방 + 이 통로 = **하나의 소라게 껍질**. 방이 몸통, 통로가 아가리.
//
//  ★★상승이 미학이 아니라 **필요조건**이다(실측 발견).
//   회랑 외벽에 붙으려면 통로가 회랑 발자국(r167.4~174.1) 안으로 든다. 그런데 통로 바닥에서
//   회랑 밑판(237.83)까지 수직 여유가 **11.40**뿐이라 층고 18짜리 통로는 **밑을 못 지난다.**
//   ⇒ 올라가는 수밖에 없고, **12.00을 올리면 통로 바닥 = 회랑 바닥(238.43)**으로 딱 떨어진다.
//   그 위는 회랑 밖이라 층고가 자유로워진다. 즉 현도의 '상승'이 '외벽 부착'을 가능케 한 열쇠다.
//
//  ★계단 = 회랑 어법 **그대로 계승**(§2-D ④ 합격작에서만 계승): 5단 × 단높이 0.24 = 한 참 1.2.
//   12.00 ÷ 1.2 = **정확히 10참**. 회랑이 9.6을 8참에 내려온 것과 같은 리듬 → 둘이 한 계통으로 읽힌다.
//
//  ★★정조준 회전각은 닫힌 식으로 유도된다(θb·R에서 파생 — 하드코딩 금지):
//     A·cos φ + B·sin φ = −R,  C = (rCL+R)(cos θb, sin θb),  A = AX+Cx,  B = Cy
//     φ = atan2(B,A) ± acos(−R/M),  M = √(A²+B²),  sweep = θb + π − φ  (양수 최소해)
//   ⚠반원호를 더 감을수록 머리가 **반대로** 돌아가 있어 되돌리는 회전이 커진다 —
//    θb 230°·R30이면 sweep 166°다(총 회전 306°, 거의 한 바퀴). 그게 소라 껍질의 대가다.
//
//  ⛔보류된 이전 판(스위치로 복귀 가능): 4차 = θb180·R70·sweep55°·사선22°·평지(16.4초, "애매").
//   3차 = 동심 R152.85(25.3초, "너무 길다"). 2차 = R40 정조준(최소반경 73, "너무 튀어나온다").
export const RM10_FLARE_ON    = true
export const RM10_FLARE_RCL   = (RM10_EXIT_RIN + RM10_EXIT_ROUT) / 2      // 반원호 보행 중심선 17.16
//  ★반원호 연장 — 구 187° → 230°. 상한 249°(입구 문 각반폭 18°가 막는다).
export const RM10_ARC_TH1     = 230 * Math.PI / 180
export const RM10_ARC_TH_MAX  = 1.5 * Math.PI - RM10_DOOR_HTH - 0.05     // 입구 문(θ270°) 앞 한계 ≈249°
export const RM10_FLARE_R     = 30      // ★노브 뒤집기 반경(작을수록 짧고 깊이 감긴다)
//  ★★두 구간 체제(5차 확정) — 회랑이 뚜껑이라 이 형태가 **강요된다**:
//   ⓐ 낮은 구간(t ≤ TB): 통로가 회랑 **밑을** 지난다. 총 높이 상한 11.40(= 회랑 밑판 − 통로 바닥).
//     여기서는 오를 수도, 커질 수도 없다. 확대·상승 지수를 7조합으로 검산했으나 전부 회랑을 뚫었다.
//     ⇒ 바깥벽이 회랑 외벽을 **아래로 연장**한다 = 현도의 '외벽 부착'이 **수직 적층**으로 성립.
//     압축 어법 계승(1p5 홀 박스 압축 = 내부고 7 → 수직 해방). 상한에서 2.8을 남긴다 —
//     공면이면 아티팩트(같은 버그 4회 전례).
//   ⓑ 터짐(t > TB): 회랑을 벗어나는 순간 계단이 시작되고 동시에 단면이 폭발한다.
//     ★검산이 맞아떨어진 것: 50단 × 디딤 0.416 = 주행 20.8 · 상승 12.0 → 경사 **정확히 30.0°**
//     = 회랑 계단 경사와 같다. 남은 1.9는 위아래 참. 면적 6×8 → 34×24 = **17배**.
//  ★★프로파일 3종(6차 — 현도 "초중반이 균일해서 기대감이 덜하다"). **셋 다 짓고 검사도 셋을 다 잰다.**
//   한 줄 교체로 로컬 비교. 구속 둘만 지키면 나머지는 취향이다:
//    ⓐ 낮은 구간 층고 ≤ 10.80(회랑 밑판) — 여유 1.0 이상 남길 것(공면 아티팩트 4회 전례)
//    ⓑ 낮은 구간 폭이 커지면 TB가 뒤로 밀려 **계단 20.78이 안 들어간다**(LO_W 16이면 여유 1.2로 빠듯)
//   ⚠등불 방은 구속이 아니다 — 이음매에서 여유 0으로 시작해 t=0.7이면 50까지 벌어진다(실측).
//   대가: 낮은 구간을 키울수록 **터짐의 배율이 준다.** 그래서 변형마다 끝 단면도 같이 키웠다.
export const RM10_FLARE_PROFILE = 'swell'   // 'compress'(5차·최대 대비) | 'swell'(권장) | 'early'(가장 이름)
const _FP = {
  //             LO_W  LO_H  ease   W1   H1      낮은구간 끝 면적 → 끝 면적
  compress:  [   6,   8.0,  1.00,  34,  24 ],   //  48 → 816  (17배) — 균일하게 참았다 터진다
  swell:     [  12,   9.8,  0.85,  40,  26 ],   // 118 → 1040 (8.8배) — 서서히 커지다 더 커진다
  early:     [  14,   9.8,  0.70,  44,  28 ],   // 137 → 1232 (9배)  — t 0.2에 이미 42% 자란다
}[RM10_FLARE_PROFILE]
export const RM10_FLARE_LO_W  = _FP[0]  // 낮은 구간 끝 폭
export const RM10_FLARE_LO_H  = _FP[1]  // 낮은 구간 끝 층고
export const RM10_FLARE_EASE  = _FP[2]  // 낮은 구간 확대 곡선(<1 = 앞에서 빨리 자란다)
export const RM10_FLARE_W1    = _FP[3]  // 터짐 끝 폭
export const RM10_FLARE_H1    = _FP[4]  // 터짐 끝 층고
export const RM10_FLARE_EASE_HI = 1.0   // 터짐 구간 확대 곡선
export const RM10_FLARE_SKEW  = 0       // ★5차: 사선 아가리 폐기(현도 "정조준으로") — 0 = 수직 아가리
export const RM10_FLARE_RISE  = 12.0    // ★상승 = CL_FLOOR_END − RM10_EXIT_FLOOR_Y 와 같은 값(아래 검산)
export const RM10_FLARE_SEG   = 72
//  ── 계단(회랑 어법 계승) ──
export const RM10_FLARE_FLIGHTS = Math.round(RM10_FLARE_RISE / (CL_STEP_N * CL_STEP_RISE))   // 10참
export const RM10_FLARE_STEPS   = RM10_FLARE_FLIGHTS * CL_STEP_N                             // 50단
//  ── 파생: 정조준 회전각 ──
export const RM10_FLARE_C = [
  (RM10_FLARE_RCL + RM10_FLARE_R) * Math.cos(RM10_ARC_TH1),
  (RM10_FLARE_RCL + RM10_FLARE_R) * Math.sin(RM10_ARC_TH1),
]
export const RM10_FLARE_SWEEP = (() => {
  const A = RM10_AX_R + RM10_FLARE_C[0], B = RM10_FLARE_C[1], M = Math.hypot(A, B)
  if (RM10_FLARE_R > M) return Math.PI / 2                       // 조준 불가 시 가드
  const al = Math.atan2(B, A), best = []
  for (const sg of [1, -1]) {
    let s = RM10_ARC_TH1 + Math.PI - (al + sg * Math.acos(-RM10_FLARE_R / M))
    while (s <= 1e-6) s += 2 * Math.PI
    while (s > 2 * Math.PI) s -= 2 * Math.PI
    //  '향한다'만 채택(정반대 해 배제)
    const f = RM10_ARC_TH1 + Math.PI - s
    const x = RM10_FLARE_C[0] + RM10_FLARE_R * Math.cos(f), z = RM10_FLARE_C[1] + RM10_FLARE_R * Math.sin(f)
    const dx = -RM10_AX_R - x, dz = -z, dn = Math.hypot(dx, dz)
    if ((Math.sin(f) * dx - Math.cos(f) * dz) / dn > 0.9999) best.push(s)
  }
  return best.length ? Math.min(...best) : Math.PI / 2
})()
export const RM10_FLARE_LEN   = RM10_FLARE_R * RM10_FLARE_SWEEP
//  ★TB = 통로가 회랑 띠(r·방위)를 벗어나는 진행. **하드코딩 금지** — 노브를 돌리면 따라온다.
//   낮은 구간의 바깥 모서리(반폭 LO_W/2 + 두께)로 잰다(그 구간은 설계상 좁다).
export const RM10_FLARE_TB = (() => {
  const hw = RM10_FLARE_LO_W / 2 + PASS_T
  const clA = CL_R - CL_HW, clB = CL_R + CL_HW + CL_WALL_T
  const cp = Math.cos(RM10_PHI), sp = Math.sin(RM10_PHI)
  let last = 0
  for (let i = 0; i <= 800; i++) {
    const t = i / 800, f = RM10_ARC_TH1 + Math.PI - RM10_FLARE_SWEEP * t
    const px = RM10_FLARE_C[0] + RM10_FLARE_R * Math.cos(f), pz = RM10_FLARE_C[1] + RM10_FLARE_R * Math.sin(f)
    const nx = -Math.cos(f), nz = -Math.sin(f)
    for (const off of [hw, -hw]) {
      const lx = px + off * nx, lz = pz + off * nz
      const wx = RM10_AX_R * cp + lx * cp - lz * sp, wz = RM10_AX_R * sp + lx * sp + lz * cp
      const r = Math.hypot(wx, wz), az = Math.atan2(wz, wx)
      if (r > clA && r < clB && az >= CL_PHI0 && az <= CL_PHI1) last = t
    }
  }
  return Math.min(0.9, last + 0.005)
})()
export const RM10_FLARE_BURST_RUN = RM10_FLARE_LEN * (1 - RM10_FLARE_TB)
//  경로 반경(돔 중심 기준) — 노브를 돌리면 검사·웨이포인트가 자동 추종
export const rm10FlareR = (s) => {
  const f = RM10_ARC_TH1 + Math.PI - s
  return Math.hypot(RM10_AX_R + RM10_FLARE_C[0] + RM10_FLARE_R * Math.cos(f),
                    RM10_FLARE_C[1] + RM10_FLARE_R * Math.sin(f))
}
//  천장 안쪽(−N) 모서리 시작값 = 방 원뿔면 추종(수직이면 이음매가 벌어진다 — ★79-6 전례)
export const RM10_FLARE_B1_0  = RM10_FLARE_RCL - (rm10R(RM10_EXIT_ROOF_Y) + RM10_CONE_T)
export const RM10_FLARE_TPLUS = Math.max(0, 1 - RM10_FLARE_SKEW / RM10_FLARE_SWEEP)   // 0 = 수직 아가리
//  입(mouth) — 로컬 직교. 웨이포인트·검사가 읽는 파생 좌표
export const RM10_FLARE_MX = RM10_FLARE_C[0] + RM10_FLARE_R * Math.cos(RM10_ARC_TH1 + Math.PI - RM10_FLARE_SWEEP)
export const RM10_FLARE_MZ = RM10_FLARE_C[1] + RM10_FLARE_R * Math.sin(RM10_ARC_TH1 + Math.PI - RM10_FLARE_SWEEP)
export const RM10_FLARE_MY = RM10_EXIT_FLOOR_Y + RM10_FLARE_RISE
// ══ ★81 출구 통로의 창 (2026.07.29 · 시험판 — 현도 "느낌만 봐보자") ═══════════
//  현도 지정: **좌측(= 돔 중심 쪽) 벽에만** · 점점 커지는 **사다리꼴** 창.
//  ⚠좌/우 실측(2026.07.29): 진행 t 기준 좌측 = up×forward = (tz,−tx).
//   +N 벽(`wDome`)이 좌측이고 반경성분 −0.24~−1.00 = 돔 중심을 향한다. −N(`wOuter`)은 우측·바깥.
//   ⚠첫 계산에서 좌우 부호가 뒤집혀 있었다 — 반대 벽에 뚫을 뻔했다. 부호는 반드시 검산할 것.
//
//  ★설계 결정 넷(현도 2026.07.29): ① 벽 = 안쪽(좌) ② 리브 여러 기 보이는 것 허용
//   ③ '점진적' = 창이 커진다 ④ 렌즈 노출 수용.
//  ⚠**이것은 LOCKED §1 시야 차단 3중의 ②(통로 외피가 먼 리브를 가림)를 여는 장치다.**
//   창 밖 = 먼 리브 39~43기(최근접 146→283). 현도가 실측을 듣고 수용했다.
//   `RM10_WIN_ON=false` 한 줄로 ★80 상태가 정확히 복원된다(시험판인 이유).
//
//  ★사다리꼴은 발명이 아니라 **파생**이다 — 창턱은 수평 고정, 위턱은 통로 천장을 따라간다.
//   낮은 구간에서 층고가 5.0→9.8로 이미 자라므로(★80), 위턱만 추종시키면 창은 저절로
//   앞으로 갈수록 키가 크는 사다리꼴이 된다. 폭도 함께 자란다(GROW).
//  ★★로컬 판정용 3체제 스위치(현도 2026.07.29 — "세 가지 변형하면서 판정할 수 있도록").
//   'off'       = 창 없음(★80 온벽) — 부재 10종·표본 143으로 정확히 복원된다
//   'trapezoid' = 사다리꼴 6장(밑변 3.47→10.41 · 배터 8° · 위턱 천장 추종)
//   'slit'      = **얇은 슬릿** — 창턱·밑변 길이는 사다리꼴 그대로 두고 키만 잘라낸다
export const RM10_WIN_MODE  = 'slit'
export const RM10_WIN_ON    = RM10_WIN_MODE !== 'off'
//  ★★슬릿 키 — **파생 상한이 있다.** 창가에 얼굴을 붙였을 때 올려다볼 수 있는 각은
//   atan(h / PASS_T)이고, 렌즈 하단이 새기 시작하는 각은 54.4°(통로 시작·가장 유리한 지점)다.
//   ⇒ h < PASS_T·tan(54.4°) = **0.838** 이면 렌즈가 **저절로 다시 봉인된다**.
//   즉 슬릿은 '얇게 보이려는' 미학이 아니라, 사다리꼴이 열었던 렌즈 누출을 되닫는 장치이기도 하다.
//   0.8 → 53.1° (여유 1.3°). 이 값을 올리면 검사가 렌즈 노출을 도로 보고한다.
export const RM10_WIN_SLIT_H = 0.8
export const RM10_WIN_N     = 6      // ★노브 창 개수
export const RM10_WIN_U0    = 5.0    // ★노브 시작 여백(원호↔나팔 이음매 뒤 — 이음매에 창을 물리지 않는다)
export const RM10_WIN_U1    = 4.0    // ★노브 끝 여백(터짐 직전 — 계단 시작점에 창을 물리지 않는다)
export const RM10_WIN_PIER  = 2.6    // ★노브 창 사이 살(기둥) 폭
export const RM10_WIN_GROW  = 3.0    // ★노브 마지막 창 폭 ÷ 첫 창 폭
export const RM10_WIN_SILL  = 1.6    // ★노브 창턱(바닥 위) — 추락 방지 + 지면 시선 차단(회랑 CL_SILL과 같은 수)
export const RM10_WIN_HEAD  = 0.9    // ★노브 인방 살(천장에서 내려온 여유)
export const RM10_WIN_TAPER = true   // ★노브 true = 위턱이 천장 추종(기울기 ≈3.7°) / false = 창 중앙 높이로 수평
//  ★★'사다리꼴'의 두 독해 — 이 각 하나가 가른다(현도 판정 대기):
//   0  = 위턱만 천장을 따르는 **직사각에 가까운** 창(기울기 3.7°는 눈에 잘 안 읽힌다)
//   >0 = **잉카식 배터** — 문선이 안으로 기울어 위가 좁다. §2-D ④ 현행 합격작(잉카 매스) 어휘.
//   배터 폭은 절대치가 아니라 **창 키에서 파생**된다 → 여섯 창이 커져도 같은 어법을 유지한다.
export const RM10_WIN_BATTER_DEG = 8
//  창 목록 — u(나팔 호길이) 구간. **낮은 구간 안에만** 산다(터짐 구간은 공개 그 자체라 창이 무의미).
//  ★슬릿도 **같은 u 구간**을 쓴다 — 현도 지정: "슬릿의 너비는 사다리꼴 창 밑변의 길이를 그대로".
//   두 체제가 같은 목록을 공유하므로 로컬에서 갈아 끼워도 창의 '자리'는 안 움직인다(비교가 정직해진다).
export function rm10Windows () {
  if (!RM10_FLARE_ON || !RM10_WIN_ON || RM10_WIN_N < 1) return []
  const uB = RM10_FLARE_LEN * RM10_FLARE_TB
  const avail = uB - RM10_WIN_U0 - RM10_WIN_U1 - (RM10_WIN_N - 1) * RM10_WIN_PIER
  if (avail <= 0) return []
  const N = RM10_WIN_N, G = RM10_WIN_GROW
  const w0 = avail / (N * (1 + G) / 2)          // Σ w_k = avail 를 만족하는 첫 창 폭(파생)
  const out = []
  let u = RM10_WIN_U0
  for (let k = 0; k < N; k++) {
    const w = w0 * (1 + (G - 1) * (N === 1 ? 0 : k / (N - 1)))
    out.push({ k, u0: u, u1: u + w, w })
    u += w + RM10_WIN_PIER
  }
  return out
}

//  ⚠★85 테라스 블록은 `RIB_DEST_PHI` 파생이라 **아래 ★61 블록 뒤**로 내려가 있다(TDZ).

// ── 통로 위치: 단면(COR_R·천장)은 동결, 원기둥이 크기 유지한 채 돔 따라 바깥으로 이동 ──
export const COR_X1     = R_BASE                    // 바깥 끝 = 탐험경선 #0 밑동(③에서 288)
export const COR_CYL_X0 = R_BASE - 2 * COR_R        // ③에서 120 (⚠맨 박스 노출 ~29 = §7 열린 결정 — 통로 만질 때)
export const COR_CX     = (COR_CYL_X0 + COR_X1) / 2 // 원통 중심 x = R_BASE − COR_R (③에서 204)
export const BOX_X1     = COR_CYL_X0 + 4            // 박스 안쪽 끝 = 원기둥 시작 + 살짝 물림
// ── ★㊵-4 드럼 복원(2026.07.20 현도: "통로 = 원래 형태(원기둥+빗면 절단)로, 부양은 유지") ──
//  구 드럼 체제(수직 원기둥 벽 + 빗면 천장 + 창 ±43°) 복원. ★단 천장은 절대치(70/150)를
//  '보행 기준 파생'으로 전환 — 부양(+52) 시 보행 단면(낮은쪽 +20.7 / 높은쪽 +100.7)이 구값과 동일하게
//  보존된다. 부산물: 높은 끝 = COR_Y0+101 = 202 ≈ 리브 시각적 휨 시작(㊵ 나팔 발견의 계승 — 천장이
//  리브 꺾임에서 끝난다). 벽·창 하단은 지면·리브 앵커 그대로(문 다섯 9~99가 창 안에 있어야 하므로).
export const CEIL_LO      = COR_Y0 + 21    // 천장 낮은 쪽(방, −x) — 구 70 = 49+21의 파생화(보행 기준 단면 동결)
export const CEIL_HI      = COR_Y0 + 101   // 천장 높은 쪽(리브, +x) — 구 150 = 49+101의 파생화 → 202 ≈ 리브 꺾임
export const CEIL_SLOPE   = (CEIL_HI - CEIL_LO) / (2 * COR_R)   // 빗면 기울기(=구식 (COR_X1−COR_CYL_X0) 항등)
export const ceilY        = (x) => CEIL_LO + CEIL_SLOPE * (x - COR_CYL_X0)  // 천장 평면 y
export const COR_WALL_SEG = 96             // 원통 벽 둘레 분할 수
// +x 벽 창(㊳ ±43° — 다섯의 프레임) — 하단·상단은 ★절대/천장 앵커(문 다섯이 지면 기준이므로 부양과 무관)
export const WIN_HALF   = 43 * Math.PI / 180   // ★창 반각 — #±2 포함(32.1°)·#±3 배제(45.1°)의 기하 근거
export const WIN_SILL_Y = 0            // 아래턱 0 = 리브를 발끝(지면)까지 (문 #−2 문턱 9 노출 필수)
export const WIN_TOP_Y  = CEIL_HI      // 위턱 = 천장
// ── 창·문·계단(㊳): [B] 절대치 블록 참조(WIN_*·HALL_DOORS·STAIR_*). ⚠구 슬릿(SLIT_*)·피어(PIER_*·
//  corWallR)는 ㊳으로 폐기 — 슬릿은 '다섯을 보인다'로 반대 요구가 됐고, 피어는 이웃 리브를 가릴 이유가
//  사라져 동반 소멸(벽 = 순수 원통 COR_R 복귀. 리브 ±1의 벽면 관통 3.4는 이제 개구 안이라 무해 — 구 파노라마와 동일). ──

// ── ★신전 프리즈(㊳→㊴) 복원 — 창 상부(y=TEMPLE_Y0~빗면 천장) 수평 부재. 리브 무절단 가림 ──
export const TEMPLE_MODE = 'beam'
// ── ★㊺ 엔타블러쳐 밑면 개구(2026.07.21 현도 — "리브가 짧게 느껴짐 → 밑면을 삼각/아치로 열어 가운데 리브 드러냄") ──
//  프리즈 밑면(y=TEMPLE_Y0)을 평평 대신 삼각(페디먼트)/아치로 파 가운데 리브(#0)가 위로 더 드러나게 한다.
//  = 그리스 신전 박공·개선문 어휘. 신전 파사드감↑ + "다섯이 같은 선에서 잘림"의 단조 해소.
//  ⚠개구는 z방향(리브 열)으로 열림 — 가운데(z=0) 최고, 양끝(z±HZ) 0. 배경(셀라)이 그 뒤를 받쳐 봉인 유지(R4절).
//  ⚠개구 하한 = 문 위(최고 문 상단 110 + 여유) — 문 다섯 온전.
export const TEMPLE_PEDIMENT = 'arch'   // ★밑면 어법 — 'flat'(평평·구 상태) / 'tri'(삼각 페디먼트) / 'arch'(아치)
export const TEMPLE_OPEN     = 50      // ★가운데(#0) 개구 높이(현도 "삼각 30 근처") — 밑면 114 → 가운데 144까지 열림
export const TEMPLE_Y0   = 114              // ★부재 하단 y — 최고 문 상단(110) 위 4(지면 앵커 — 문과 함께 불변)
export const TEMPLE_X0   = COR_CX + COR_R * Math.cos(43 * Math.PI / 180) - 1.5   // 앞면 ≈263.9 = 창 모서리 − 1.5
export const TEMPLE_X1   = 298   // ★55-2(2026.07.24): 295 → 298 = 셀라 동벽 안면. 프리즈를 3 깊게 한다.
//  ⚠왜: 프리즈 방에서 리브 뒤 여유가 실측 #0 **−2.0** · #±1 −0.9(= 벽 속에 박힘) · #±2 2.4였다.
//   셋이 벽에 붙어 보이면 1p7("실체는 아무것에도 의존하지 않는다")이 정확히 반대로 읽힌다.
//   동쪽 상한은 셀라 동벽 안면 298(그 밖은 돔 리브 케이지 바깥) — 여기까지가 봉인을 안 건드리는 최대치.
//   홀에서 보이는 변화 = 아치 터널이 3 길어지는 것뿐(앞면 TEMPLE_X0 불변 = 신전 얼굴 무변경).              // 뒷면 — 리브 관 단면(x≤294) 포함 여유 1
export const TEMPLE_HZ   = 62               // z반길이 — 창 전폭(±57.3) + 리브 #±2 관 여유
export const TEMPLE_CLR  = 0.4              // 관통 구멍 반경 여유
export const TEMPLE_COLOR = '#b89a6a'       // ★60(2026.07.24) 프리즈 석재 톤 — 구 TempleBeam 하드코딩을 상수로.
//  ⚠프리즈 방 바닥이 곧 이 부재의 살이므로, 방 안에 놓이는 바닥 부재(★60 문지방)가 같은 값을 읽어야
//   '바닥이 손을 내민 것'으로 읽힌다. 두 곳에 따로 적힌 색은 반드시 어긋난다(㊾ 계승 규칙의 색 판).

// ── ★셀라(CELLA, 내진) ㊶ 2026.07.20 — 창 밖 다섯 리브 구역을 '서면(창 쪽)만 뚫린 직육면체'로 감싼다(현도 안) ──
//  §7 ⑦(리브 틈 하늘 비침 — 신전 파사드 희석)의 후보 (b) 실현. 덤 = 창가 근호 노출(구 동시 최대 15)이
//  옆벽·동벽에 기하로 차단돼 '다섯'으로 떨어진다(O절 봉인). 이름 = 신전 어휘의 연장: 파사드(프리즈) 뒤에서
//  신상(다섯 실체)을 모시는 내진(cella). 리브 다섯은 지붕을 '관통'해 위로 계속 = TempleBeam pierce 어휘
//  ("실체는 아무것도 이지 않는다" — LOCKED 무결. 구멍은 프리즈 구멍과 동축·동반경이라 한 구멍으로 이어짐).
//  ⚠구축 원리(Corridor.Cella): 드럼 벽 = 두께 0 셸(r=COR_R)이라 직선 슬랩이 곡벽을 지나면 홀 안쪽으로
//  지느러미가 삐진다 → 슬랩 유니온에서 드럼 내부 원기둥(CELLA_BITE_R)을 CSG로 절제(안쪽 돌출 ≤ 0.2 =
//  셸에 붙은 불가시 슬리버·곡벽 물림 봉인을 한 수로).
// ══ ★55 프리즈 방 — 1p7의 집(2026.07.24 · 현도 스케치·확정) ══
//  왜: 리브 안 나선을 타고 오르면 **리브가 끝나는 것이 보이고**, 이 방으로 나와 다섯이 하나같이
//   **아무것에도 닿지 않고 떠 있는 것**을 본다 = 1p7("실체의 본성에는 존재가 속한다")의 직시.
//   구 1p7(폴 절단 = 가설이 끊기고 디딤판이 뜸)의 계승이되 대상이 디딤판 → **실체 자신**으로 올라간다.
//   ⚠구 1p6·1p7(폴 절단) = **현도 폐기 확정**(2026.07.24). 1p6은 이 방 아래 나선 부근 — 별도 세션.
//  ★이 자리여야 하는 이유(실측): 리브를 끊으면 LOCKED(72개 기하 동일)를 건드리는데,
//   프리즈 방은 **끊어도 어느 시점에서도 안 보이는 유일한 곳**이다 — 아래는 바닥이, 위는 빗면 천장이 막는다.
//   LOCKED 예외 #1(문 뚫린 리브 다섯)이 "다른 시점 불가시"를 조건으로 허용된 것과 같은 논리.
//  ⚠**바닥 두께가 봉인 조건이다**: 아치 크라운이 정확히 y164(=TEMPLE_Y0+TEMPLE_OPEN)라
//   바닥 상면을 y164에 두면 가운데 두께가 0이 되어 **아치 터널로 뻥 뚫린다**(홀에서 방 안이 보임).
//   그래서 FR_FLOOR_T는 미학 노브가 아니라 하한이 있는 봉인 노브다(검증이 강제).
//  형태: 바닥 밑면 = 아치 등 그대로(§2-D ② "매스 + 깎인 밑면") · 천장 = 빗면 추종(동쪽이 높다).
export const FRIEZE_ROOM_ON = true
export const FR_FLOOR_T = 2    // ★바닥 두께(아치 크라운 위로) = 방 바닥 높이의 유일한 레버.
//  ⚠0이면 아치 크라운에서 뚫려 봉인 파탄. **하한 2**의 근거는 CSG가 아니다 —
//  실측(2026.07.24): 두께 5·3·2·1 전부 CSG 성립(NaN 0·바닥면 정점 1900+). 즉 기하는 1도 된다.
//  하한 2를 두는 건 ①밟는 면이라 최소한의 살 ②봉인 여유(그림자·스침 각) 때문. 미적 판단으로 낮추려면
//  검사 [101]의 문구와 함께 내릴 것 — 근거 없이 숫자만 바꾸면 다음 세션이 이유를 잃는다.
export const FR_WALL_T  = 3    // 앞(홀 쪽)·옆 벽 두께 — 앞벽이 신전 얼굴이라 얇으면 안 된다
export const FR_BACK_T  = 1.5  // ★뒷벽만 따로 — 리브 뒤 여유를 버는 노브. 여기는 얼굴이 아니라 살만 있으면 된다
// ★55-3 뒤 별채(2026.07.24 · 현도 "아직 공간감 부족"): 프리즈 뒷면(298)에서 동쪽으로 더 채운다.
//  ⚠왜 프리즈 자체를 더 깊게(TEMPLE_X1↑) 안 했나: 그러면 **홀에서 보는 아치 터널이 같이 깊어진다**
//   (아치는 프리즈를 관통하는 터널이므로). 아치 얼굴은 현도가 ㊺에서 판정한 것이라 안 건드린다.
//   별채는 y164(아치 크라운) **위에만** 얹히므로 아치 터널·배경벽은 무변경이다.
//  ⚠상한 302 = 셀라 바깥면. **거기까지는 새 돌출이 0**이다 — 셀라가 이미 x302까지 나가 있어서
//   별채가 그 발자국 안에 들어간다(조감 무변경 · 밑면은 배경벽 y115.5~170이 그대로 받는다).
//   302를 넘기려면 신전이 동쪽으로 실제로 더 튀어나오는 것 = 조감 판정이 붙는다(현도 몫).
export const FR_CEIL_T  = 3    // 천장 두께(빗면 천장 밑으로) — 돔 쪽 누출 방지
export const FR_FLOOR_Y = TEMPLE_Y0 + TEMPLE_OPEN + FR_FLOOR_T   // 파생 = 방 바닥 상면(현행 값 y166 — TEMPLE_OPEN 50 기준)

// ══ ★77 프리즈 방 서벽(드럼 쪽) 창 — 1p7의 방에 빛을 들인다 (2026.07.28 · 현도 지시) ══
//  왜: 방이 완전 밀폐라 빛이 들어올 구멍이 없었다. 서벽은 드럼 창(±43°) 개구 안에 서 있어
//   그 너머가 곧 홀이다 → 여기에 구멍을 뚫으면 홀의 빛이 방으로 들어온다. **유리 없음 = 순수 개구.**
//  ⚠**벽 두께는 이미 있다(FR_WALL_T=3).** 두께 0인 것은 드럼 원통 셸이지 이 벽이 아니다(2026.07.28 실측).
//   그래서 창은 '두께 3의 인방(reveal)을 가진 구멍'이고, 빛이 그 깊이만큼 깎여 들어온다.
//
//  ★★봉인 문제(2026.07.28 실측 — 반드시 읽을 것):
//   홀 안 시점 전수(드럼 내부 전역 × 눈높이 39.9~103, 표본 17.5만) × 리브 다섯의 간극 점으로
//   광선을 쏴 서벽 바깥면 통과 높이를 다 구했다. **최고 통과 높이 = y180.03**
//   (구속 시점 = 박스 목 x122·y101.9 = 하강로 시작 / 구속 표적 = 리브 #+2 간극).
//   → **창턱이 FR_WIN_SEAL_Y 위면 홀에서 절단이 안 보이고, 아래면 보인다.**
//   창턱별 노출: 166→다섯 전부 · 172→#−1·#+2 · 178→#+2 · 182 이상→없음.
//  ⚠**현도 판정(2026.07.28): 'grand'는 봉인선 아래로 내려간다 = LOCKED 예외 #2 조건 ②를 연다.**
//   "일단 봐보자" — 로컬 육안 판정 후 유지/철회를 정한다. 검사는 막지 않고 **노출 리브를 보고**한다
//   (막으면 판정을 못 한다. 대신 비용이 매 실행마다 눈에 보이게 남는다).
export const FR_WIN_MODE = 'slit'   // ★'none' | 'slit'(천장 슬릿·봉인 유지) | 'grand'(통창·봉인 열림)

//  ── 안 ① 슬릿(천장 가까이) — 봉인선 위에 갇힌다. 쓸 수 있는 세로는 180.03~187.5 = 7.5뿐 ──
export const FR_WIN_SLIT_SILL = 183   // 창턱 y (> FR_WIN_SEAL_Y 라야 봉인 유지)
export const FR_WIN_SLIT_HEAD = 187.9   // 창 상단 y (≤ FR_WIN_HEAD_MAX) — 천장 밑 1.05
export const FR_WIN_SLIT_HZ   = 55      // z 반폭 (≤ FR_WIN_HZ_MAX — 옆벽 살 보존)

//  ── 안 ② 통창 — 벽을 세로로 가로지른다. 봉인선 아래 ──
export const FR_WIN_GRAND_SILL = 168.5
export const FR_WIN_GRAND_HEAD = 187.9
export const FR_WIN_GRAND_HZ   = 55

//  ── 창살(세로살만 — 현도 지정). 개수·간격은 **리브에서 파생**한다(하드코딩 금지 불변식) ──
//   ⚠커플링: 리브 방위(hallDoors)가 바뀌면 살도 따라 움직인다. 두 곳에 따로 적으면 반드시 어긋난다.
export const FR_WIN_BAR_ON    = true
export const FR_WIN_BAR_ALIGN = 'between'   // 'rib' = 리브 z에 정렬(개수 5) / 'between' = 리브 사이(개수 4)
export const FR_WIN_BAR_W     = 0.7     // 살 폭(z 방향)
export const FR_WIN_BAR_SET   = 0.5     // ★파사드 면에서 **후퇴** — 0으로 두면 벽 앞면과 정확히 동일 평면이 된다
                                        //   (★75 폭 사슬 교훈: 두 값이 정확히 같으면 반드시 아티팩트가 난다)
export const FR_WIN_BAR_IN    = 0.4     // 방 쪽으로 내민 깊이 — 안쪽면과도 동일 평면이 되지 않게
export const FR_WIN_BAR_BITE  = 0.4     // 위·아래로 벽에 물리는 깊이(안 물리면 살이 허공에 뜬 막대가 된다)

//  ── 파생·한계 (직접 건드리지 말 것) ──
export const FR_WIN_ON   = FRIEZE_ROOM_ON && FR_WIN_MODE !== 'none'
export const FR_WIN_SILL = FR_WIN_MODE === 'slit' ? FR_WIN_SLIT_SILL : FR_WIN_GRAND_SILL
export const FR_WIN_HEAD = FR_WIN_MODE === 'slit' ? FR_WIN_SLIT_HEAD : FR_WIN_GRAND_HEAD
export const FR_WIN_HZ   = FR_WIN_MODE === 'slit' ? FR_WIN_SLIT_HZ   : FR_WIN_GRAND_HZ
//  ★상단 한계 = **방 천장**(서벽 안쪽면에서의 천장 밑면). 바깥면 돌 끝(190.5)이 아니다 —
//  바깥면이 아니라 천장이 먼저 걸린다. 넘기면 창이 천장 슬래브를 파고들어 방 천장 서쪽 모서리가
//  이 빠진 자국이 된다(창이 아니라 홈이 된다). 2026.07.28 초안이 바깥면으로 잡았다가 정정.
export const FR_WIN_HEAD_MAX = ceilY(TEMPLE_X0 + FR_WALL_T) - 0.02 - FR_CEIL_T - 0.5
export const FR_WIN_SILL_MIN = FR_FLOOR_Y + 0.5          // 바닥 살 보존
export const FR_WIN_HZ_MAX   = TEMPLE_HZ - FR_WALL_T - 2 // 옆벽 살 보존
//  ★봉인선 — 실측값(2026.07.28). 리브 절단 높이(RIB_CUT_SEED)나 시점 봉투가 바뀌면 **다시 재야 한다**.
//  검사 V절이 매 실행마다 실제로 재유도해 이 값과 대조한다(숫자만 남고 근거를 잃는 것 방지).
export const FR_WIN_SEAL_Y = 180.04

// ══ ★56 리브 절단 — 1p7의 몸(2026.07.24 · 현도 지정) ══
//  왜: 55가 방(껍데기)을 팠고, 56이 그 안에서 **실체를 끊는다**. 1p7 "실체의 본성에는 존재가 속한다" —
//   증명은 1p6("다른 실체에서 산출될 수 없다")에 기대므로, 리브 밑에 **아무것도 없어야** 한다.
//   → 다섯 리브를 끊고 윗토막이 아무것에도 닿지 않고 떠 있게 한다. 관람자는 그걸 **아래에서 올려다본다**.
//
//  ★★LOCKED 예외 #2(§1 — 예외 #1〔홀 문 다섯〕의 확장, 같은 논리로만 성립):
//   ① 대상 = **프리즈 방을 지나는 다섯(#0·#±1·#±2)뿐**(현도 ⓐ). 나머지 67은 무결.
//   ② **다른 시점에서 절단이 보이면 안 된다** — 이 방이 유일하게 가능한 자리인 이유가 그것이다.
//      아래는 방 바닥(FR_FLOOR_Y)이, 위는 빗면 천장(ceilY−FR_CEIL_T)이 막는다. 그래서 절단은
//      **[FR_FLOOR_Y, 천장−RIB_CUT_HEAD] 안에 갇혀야 하고**, 이건 미학이 아니라 봉인 조건이다(R6절이 강제).
//   ③ 리브의 곡선·굵기·재질·불투명성은 **불변**. 달라지는 건 '있다/없다'뿐 — 형태 차별화가 아니다.
//
//  ★왜 다섯의 높이가 제각각인가(현도 ⓑ "절단 높이 무작위 지향"): 다섯을 같은 높이에서 끊으면
//   그 선 자체가 **공통의 기준면**이 되어 "무언가가 다섯을 함께 결정했다"로 읽힌다 — 1p7의 정반대다.
//   높이가 서로 무관해야 각자가 제 본성으로 서 있다는 진술이 된다. 1p5 문 높이 불규칙과 같은 어법.
//  ⚠단 '진짜 난수'는 두 개가 우연히 겹쳐 **쌍**(= 질서)을 만들 수 있다 → 층화 추출(stratified) 후 섞음:
//   창을 다섯 띠로 나눠 한 리브에 하나씩 배정하면 **간격은 불규칙하되 겹침은 불가능**하다.
export const RIB_CUT_ON   = true      // 스위치(폐기 = 한 줄). false면 55 프리즈 방만 남고 리브는 무결
export const RIB_CUT_MODE = 'floor'   // ★★현도 로컬 판정(둘 다 구현 — ⓓ "아랫토막은 바닥에서 끝남"의 두 독해):
//   'floor' — **바닥에서 끊긴다.** 방 안에 아랫토막이 없다. 바닥에는 리브의 절단면(원판)만 남고
//             그 위는 허공, 그다음 떠 있는 윗토막. 밑에 아무것도 없음이 가장 세다.
//             ⚠부수 효과: 절단면 원판이 **바닥 관통 구멍(반경 SHELL_RIB_R+TEMPLE_CLR)을 메운다** —
//              끊은 자리가 바닥 무늬가 된다(톱으로 밑동을 자른 기둥). 구멍 봉인도 같이 해결.
//   'stub'  — **그루터기가 남는다.** 바닥에서 임의 높이까지 아랫토막이 올라오고, 그 위에 간극.
//             '끊겼다'는 사건이 눈에 보이는 대신, 그루터기가 윗토막을 가리켜 '원래 이어져 있었다'로 읽힐 위험.
export const RIB_CUT_SEED    = 22   // ★시드(결정론 — 렌즈 LENS_SEED 전례). 갈아끼우며 다섯 높이의 배열을 고른다.
//  ★★★61 재선택(2026.07.24 · 구 시드 6 근거 무효화): #0 나선은 이제 프리즈 방 바닥에서 **끝나므로**
//   "#0 간극을 나선이 건넌다"는 판정 기준이 아니다. 새 기준 = **목적지 리브(#+2)의 간극이 오를 만한가**
//   (자립 나선의 높이 = #+2 윗끝 − 방 바닥 166). 시드 1~24 스캔 실측:
//   · 22(채택) — #+2 상승 **24.8 = 71칸 ≈ 1.8바퀴**(최대) + #0 윗끝 182가 다섯 중 한가운데(평범 계승)
//   · 차점: 21(23.7 · #0 2위) · 9(23.3 · #0 3위) · 17(21.1 · #0 5위) — 로컬 왕복 대안
//   · 구 6은 #+2 상승 8.0(23칸)으로 자립 나선이 사건이 못 된다. 갈아끼워도 검증은 자동 추종.
export const RIB_CUT_GAP_MIN = 8    // ★간극 하한(현도 ⓒ "1p5 GAP(5)보다 크게"). 나선 ≈23칸 = 반 바퀴 넘게 건넌다
export const RIB_CUT_HEAD    = 3    // 윗토막 밑끝 ↔ 방 천장 최소 여유 — **봉인 여유**(위에서 절단이 안 보이게)
export const RIB_CUT_STUB_MIN = 4   // 'stub' 전용 — 그루터기 최소 높이(바닥 위). 창의 아래끝을 이만큼 밀어 올린다
export const RIB_CUT_SEP     = 3    // ★다섯 '윗토막 밑끝'의 최소 세로 이격.
//  ⚠이게 없으면 층화만으로는 부족하다 — 이웃 띠의 두 표본이 경계에 붙어 1.3까지 근접하는 걸 실측했다(첫 구현).
//   그러면 그 둘이 **쌍**으로 읽히고 쌍은 질서다(불변식 ③ 위반). 그래서 '최소 이격 + 남는 여유를 무작위 분배'로 뽑는다:
//   정렬한 균등난수 다섯에 여유(창−SEP×4)를 실어 얹고 i·SEP를 더하면 **이격은 보장되고 간격은 불규칙**하다.
//  ⚠상한은 창이 정한다 — SEP×4 ≤ 공통 창 높이여야 해가 존재(R6이 잡는다).
export const RIB_CUT_BOX_HW  = 9    // 절단 브러시 반폭 — 관 반경 6 + 여유 3(간극 구간 x드리프트 최대 ≈2 흡수).
//  ⚠상한은 이웃 리브 간격(방위 5° ≈ 25.1) — 여기 넘기면 옆 리브까지 끊는다. R6이 상한을 잡는다.
export const RIB_CUT_CAP_T   = 0.3  // 절단면 캡 두께 — 잘린 단면을 막는 판(구 폴 절단 '평면 캡' 어휘 계승).
//  ⚠캡이 없으면 관이 **뚫린 파이프 아가리**가 되어 보어가 그대로 열린다(아래로는 홀까지). 봉인 부재다.
export const RIB_CUT_CAP_MG  = 0.12 // 캡 반경 여유 — 기운 관을 수평으로 자르면 단면이 타원(장축 = R/cos θ)이라 그만큼 넘겨 덮는다

// ══ ★57 리브 벽 두께 — 종잇장에서 건축으로(2026.07.24 · 현도 지정) ══
//  왜: 관이 두께 0 셸이라 문·아치·절단면이 전부 **종잇장 모서리**로 끝난다(현도 로컬 소견).
//   실제 건축이면 벽에 살이 있고, 개구를 뚫으면 그 살이 인방·문선(reveal)으로 드러난다.
//
//  ★★방향은 '안쪽으로'만 가능하다 — 바깥 반경 6.0은 못 건드린다:
//   ① 바깥을 키우면 그게 곧 §1이 금지한 **굵기 차별화**다(테라스·1p11에서 #0만 굵어 보이면 반전이 죽는다).
//   ② §1 실측: 두께 단독 증가는 꼭대기 융합(이웃 간격 < 지름)으로 물리 불가.
//   → 바깥면은 72기 완전 동일(TubeGeometry 그대로 재사용), 안쪽에만 살을 붙인다.
//
//  ★★상한 0.509 — 이건 취향이 아니라 실측이다(2026.07.24 `_probe_bore`):
//   보어 안 요소의 중심선까지 수직거리 최대 = **무릎길 계단 5.491**(x≈260·y≈223). 나선 디딤판은 4.084,
//   착지 판넬 4.107이라 여유가 1.9씩 있지만, **가장 빡빡한 하나가 전체를 정한다**.
//   ⚠§7에 적힌 '5.71 · 여유 0.29'는 다른 정의(x안쪽 모서리+z)로 잰 값이다. 관 내벽은 중심선에서
//    수직거리로 놓이므로(TubeGeometry = Frenet 프레임) 위 5.491이 맞는 수다. §7 수치는 정정 대상.
//   ⚠더 두껍게 하려면 무릎길을 안으로 밀어야 하고, 그건 1-③F·③G에서 이미 닫힌 결정을 다시 여는 일이다.
//    (여유가 큰 아래 구간만 두껍게 하는 '테이퍼 벽'은 가능하나 새 어휘라 현도 판정 사항 — §7에 열어 둠.)
export const RIB_WALL_ON = true
//  ★★상한은 파생이다 — 관이 **원기둥이 아니라 정 RIB_RADIAL_SEG 각형**이기 때문:
//   내벽의 최근접점은 꼭짓점(반경 R−t)이 아니라 **평면**(반경 (R−t)·cos(π/N))이다.
//   그래서 무릎길이 안 뚫리려면  (R−t)·cos(π/N) ≥ 보어 최대 축거리  →  t ≤ R − 축거리/cos(π/N).
//  ⚠구 계산 0.509는 원기둥으로 가정한 값이라 **과대평가**였다(꼭짓점 기준). 실제는 아래.
//  ★65(2026.07.25): **모드 추종**으로 승격. KW_BODY_MODE가 KW_FLATTEN을 바꾸므로 보행선이 통째로 달라진다 —
//   'fill'은 보행선 무변경이라 구값 그대로, 'girder'는 보행선이 올라가 보어가 헐거워지고(4.635) 대신
//   **몸(사다리꼴 배)이 새로 가장 빡빡한 요소**가 된다(배 밑끝 ≈5.37). 그래서 girder 값은 몸 기준이다.
//   ⚠'fill' 몸은 이 수에 안 들어간다 — 그 몸은 **벽이 깎아 만든 것**이라 벽보다 깊을 수 없다(정의상 무의미).
//    대신 R11절이 '몸이 관 밖으로 안 샌다'를 따로 잰다. 자립 요소만 이 수에 들어간다(R7절 주석 참조).
//  ★69(2026.07.25): 보행면을 관 바닥에서 띄우면서 **5.375 → 4.510**으로 떨어졌다.
//   ★부수 효과가 크다 — 벽 두께 상한이 0.226 → **1.258**로 열린다. 현도가 "22cm 벽 / 12m 보어는
//   석조로는 얇다"고 적어 둔 제약이 사라진 셈이다(RIB_WALL_T는 아직 0.22 그대로 — 올리면 관 내반경이
//   줄어 ★69 클램프에 되먹임되므로 별도 판정 사항, §7에 열어 둔다).
export const RIB_BORE_MAX_AX = _GIRDER ? 5.2531 : 4.510  // 실측(2026.07.24 `_probe_bore` / ★65 girder는 07.25 `_probe_bore65` 재유도 = 몸 밑변)
//  ⚠이 수는 무릎길 노브(KW_FLATTEN·X_LAND_HI 등)를 만지면 변한다. 검증(R7절)이 **실제 무릎길에서 매번 다시 유도**해
//   이 상수와 대조하므로, 낡으면 검사가 먼저 죽는다(수치를 손으로 고치기 전에 검사 메시지를 볼 것).
export const RIB_WALL_T_MAX = SHELL_RIB_R - RIB_BORE_MAX_AX / Math.cos(Math.PI / RIB_RADIAL_SEG)  // 파생 ③에서 ≈0.226
export const RIB_WALL_T  = 0.22   // ★벽 두께(안쪽으로) — 상한 RIB_WALL_T_MAX(≈0.226) 바로 아래.

// ════════ ★75-f 리브 구멍(ARCH) — 하강이 관을 빠져나가는 자리 ════════
//  ⛔★75 재유도(2026.07.26 현도 적발 "리브 구멍이 잘못 뚫렸다"). 나는 이 창을 구 `X_DESC0`에
//   **동결**했었다 — ㊾ 드럼 출구를 지키려는 의도였는데, 정작 이 창은 **정션 하강이 관을 빠져나가는
//   자리**다. 하강을 42°로 세우자 그 자리가 179.1 → 184.18로 옮겼는데 창은 안 따라왔다.
//   ⚠세 축이 다 어긋났다: x 5.1 서쪽 · y는 보행선보다 1.4 위 · 폭 2.80은 구 채널(4.6) 기준.
//  ★이제 **보행선과 관 바닥의 교점**에서 파생한다(`descPierceX`). 경사·시작을 돌리면 창이 따라온다.
//  ⚠자르개는 딱 필요한 범위만(★64-5) — 반폭 1.6 · 위아래는 그 구간 보행선의 실제 최저/최고에서 유도.
const _PIERCE_HW = 1.6                     // 창의 x 반폭(살 0.22를 비스듬히 지나므로 여유)
export const ARCH_HEAD = 2.6               // 통과 머리 여유(문틀 안쪽 높이)
//  보행선(하강)과 관 안쪽 바닥 — 둘의 교점이 '살을 뚫는 자리'다.
//  ⚠constants는 junctionGeometry를 못 부른다(순환) → 여기서 직접 푼다. 두 곳의 식이 갈리지 않도록
//   junctionGeometry의 `descFloorAt`/`tubeBottomAt`은 **이 정의를 그대로 재현**해야 한다(검사 O절이 대조).
const _descFloor = (x) => x >= X_DESC0 ? U_KNEE_END * H + 0.1
  : x <= X_DESC_END ? PASS_FLOOR_Y
  : (U_KNEE_END * H + 0.1) - (X_DESC0 - x) * DESC_SLOPE
const _axisD = (x, y) => {
  let b = 1e18
  const u0 = Math.max(0.14, (y - 8) / H), u1 = Math.min(0.42, (y + 8) / H)
  for (let u = u0; u < u1; u += 0.0004) { const dr = rOf(u) - x, dy = u * H - y; const d = dr * dr + dy * dy; if (d < b) b = d }
  return Math.sqrt(b)
}
const _tubeBottom = (x) => {
  const R = RIB_WALL_ON ? SHELL_RIB_R - RIB_WALL_T : SHELL_RIB_R
  const yc = H * uOfX(x)
  let lo = yc - 9, hi = yc
  for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (_axisD(x, m) <= R) hi = m; else lo = m }
  return hi
}
export const ARCH_PIERCE_X = (() => {
  let lo = 176, hi = 191                    // hi = 보행선이 관 안 · lo = 관 밖
  for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2
    if (_descFloor(m) < _tubeBottom(m)) lo = m; else hi = m }
  return (lo + hi) / 2
})()                                        // ③≈184.18
//  ★서쪽 끝은 **방 입구까지** 간다(2026.07.26 현도: "리브 꺾이는 부분이 안 뚫려서 노출된다.
//   직육면체 방 입구와 겹치는 부분을 딱 뚫으면 될 것 같다").
//  ⚠실측한 증상: 창 서쪽 끝(182.60)~방 처마(181.23) **1.37 구간에서 살이 통로를 막처럼 가로지른다**
//   (살 밑면 252.03~252.68, 보행 머리보다 2.6~4.1 위). 그 위는 계단 볼트가 이미 비운 공간이라
//   **살 한 겹만 떠 있는 꼴**이었다 — 통과에는 지장이 없어 머리 여유 검사가 못 잡았다.
//  ★현도(2026.07.26): "어차피 아치 너머는 새로운 방이니까, 외부에서 봤을 때 안 뚫릴 정도로만
//   리브 구멍 좀 넉넉히 뚫어도 될 듯." → 방 안쪽으로 `ARCH_ROOM_BITE`만큼 더 문다.
//   ⚠상한은 봉인이다 — 넓힐 때마다 `_probe_leak75.mjs` 차분을 재서 0인지 확인한다(실측 습관).
//  ⛔0으로 되돌림(2026.07.26). "넉넉히 물어라"는 현도 지시였지만, 방 아치 벽이 생긴 뒤에는
//   **물수록 잘린 가장자리가 방에 노출된다**(현도 재적발: "출구 앞에서 찌꺼기"). 벽이 다 가리게 두고
//   구멍은 벽 뒤에서만 존재하면 앞에서 찌꺼기 0 · 뒤에서 완전히 덮인다 = 요구가 그대로 만족된다.
//  ★75-n 창의 서쪽 끝 = **문틀 서쪽 면**. 딱 거기까지다.
//   더 물면 잘린 가장자리가 방에 노출되고(현도 적발), 덜 물면 살이 문 안에 입술로 남는다.
//   문틀이 그 구간을 덮으므로 **그 안에서는 얼마든지 잘라도 안 보인다** — 클램프도 여기서 풀린다.
export const ARCH_ROOM_BITE = RM_MOUTH_REVEAL
export const ARCH_X0 = Math.min(RM_X1 - ARCH_ROOM_BITE, ARCH_PIERCE_X - _PIERCE_HW)
export const ARCH_X1 = ARCH_PIERCE_X + _PIERCE_HW
//  y는 그 구간 보행선의 실제 최저(서쪽 끝)와 최고(동쪽 끝 + 머리)에서 유도한다 — 상수 이식 금지.
export const ARCH_Y0 = Math.min(_descFloor(ARCH_X0), _descFloor(ARCH_X1)) - PASS_T - 0.15
//  ★위 끝은 "살을 전부 걷어내는 높이"에서 유도한다 — 상수로 박으면 경사·폭이 바뀔 때 또 막이 남는다.
//   관 안쪽 바닥은 |z|가 커질수록 올라가므로 **창 모서리(|z| = 폭 반)에서** 재야 한다.
const _tubeInnerBottomAtZ = (x, z) => {
  const R = RIB_WALL_ON ? SHELL_RIB_R - RIB_WALL_T : SHELL_RIB_R
  const rr = Math.sqrt(Math.max(0, R * R - z * z))          // 그 z 단면에서 남는 반경
  const yc = H * uOfX(x)
  let lo = yc - 9, hi = yc
  for (let k = 0; k < 40; k++) { const m = (lo + hi) / 2; if (_axisD(x, m) <= rr) hi = m; else lo = m }
  return hi
}
export const ARCH_Y1 = (() => {
  const hw = PASS_HW + PASS_T
  let top = _descFloor(ARCH_X1) + ARCH_HEAD                  // 최소한 통과 높이는 확보
  for (let x = ARCH_X0; x <= ARCH_X1 + 1e-9; x += 0.05)
    for (const z of [0, hw * 0.7, hw])
      top = Math.max(top, _tubeInnerBottomAtZ(x, z) + 0.1)   // 살 안쪽면까지 확실히 걷어낸다
  return top
})()
//  z는 채널 안쪽 폭 + 볼벽 살 — 창이 좁으면 벽 모서리가 유령으로 남는다(구 2.80은 새 채널에 안 맞았다)
export const ARCH_Z0 = JCT_DN_Z - (PASS_HW + PASS_T), ARCH_Z1 = JCT_DN_Z + (PASS_HW + PASS_T)
//  ★75-m 방 안쪽 구간에서 자르개가 **반드시 넘어야 하는 높이**.
//  ⛔직전 사고: "문 위 파인 자국"을 없애려고 방 안쪽 크라운을 **문 높이(253.23)에 잠갔는데**,
//   그 자리 살 밑면이 253.24~253.34로 **0.01~0.11 더 위**였다. 딱 그만큼이 안 잘려 문 안쪽 상단
//   양 모서리에 얇은 날개로 남았다(현도 적발).
//  ★잘못은 "문 높이"라는 **기하와 무관한 값**을 기준으로 삼은 것이다. 기준은 살이어야 한다.
//   여기서 그 최솟값을 구하고, 문 높이가 그보다 낮으면 **문을 그만큼 올린다**(≤0.15라 형태 영향 없음).
//   그러면 살은 전부 잘리고 파인 깊이는 0이 된다 — 두 요구가 동시에 만족된다.
export const ARCH_ROOM_CROWN = (() => {
  const hw = (ARCH_Z1 - ARCH_Z0) / 2 + 0.25          // 자르개 반폭
  const dhw = PASS_HW + PASS_FUSE                    // 문 반폭
  //  ⚠"살을 다 걷어라"를 **전 범위**에 걸면 자르개가 문보다 훨씬 넓어 곡률 벌점이 커지고(문이 1.80 올라감),
  //   정작 그 바깥 살은 문으로 보이지도 않는다. → **보이는 (x,z)에서만** 요구한다.
  //   문 천장이 크라운에 의존하므로 고정점 반복으로 푼다(3회면 수렴).
  let crown = PASS_FLOOR_Y + RM_MOUTH_H
  for (let it = 0; it < 4; it++) {
    const dsp = Math.max(PASS_FLOOR_Y + 0.05, crown - dhw)
    const doorCeil = (z) => {
      const zz = Math.abs(z) / dhw
      return zz > 1 ? -Infinity : dsp + (crown - dsp) * Math.sqrt(Math.max(0, 1 - zz * zz))
    }
    let need = PASS_FLOOR_Y + RM_MOUTH_H
    for (let x = Math.max(ARCH_X0, RM_X1); x <= RM_X1 + PASS_T + 1e-9; x += 0.04)
      for (let z = 0; z <= dhw; z += 0.06) {
        const T = _tubeInnerBottomAtZ(x, z) + 0.06
        //  ⚠문 가림은 **문보다 동쪽**에만 적용된다. 문턱 앞(방 안쪽)의 살은 문이 못 가리므로
        //   그대로 다 걷어야 한다 — 1차 계산이 여기까지 필터를 걸어 12점이 남았다(현도 적발).
        if (T > doorCeil(z)) continue      // 벽 동쪽만 다루므로 문 가림이 항상 적용된다
        const sq = Math.sqrt(Math.max(0, 1 - (z / hw) * (z / hw)))
        need = Math.max(need, T + hw * (1 - sq))     // 자르개 천장이 그 z에서 T를 넘게 하는 크라운
      }
    if (Math.abs(need - crown) < 1e-4) break
    crown = need
  }
  return crown
})()   // ③ ±2.0

//  ⚠눈높이 EYE 1.6이 사람 키 ≈1.6m이므로 1단위 ≈1m — 즉 이 값은 **22cm 벽 / 12m 보어**다.
//   종잇장(0)은 확실히 면하지만 석조로는 얇다. **두껍게 하는 레버는 두께가 아니라 `RIB_RADIAL_SEG`다**:
//    SEG 10→12 상한 0.32 · 10→16 상한 0.40 · 10→24 상한 0.46(관이 둥글어질수록 평면 손실이 줄어든다).
//   ⚠단 SEG는 **72기 전부가 공유**하는 값이라(형태 동일 LOCKED) 올리면 리브 실루엣이 다 같이 둥글어지고
//    삼각 수도 비례해 는다(SEG16 = 리브당 6400). 미학·성능 판정이라 현도 몫 — §7에 열어 둠.
export const RIB_WALL_SCOPE = 'cut5'   // ★★현도 로컬 판정(둘 다 구현):
//   'explore' — **여정 리브만**. ★61(07.24)로 여정이 두 리브가 되며 1→2기: #0(오르는 관) + RIB_DEST_K
//               (#+2, 계속 오르는 관). 들어가는 관에만 살 = 문·아치와 같은 '합의된 기능'(예고된 개정 그대로).
//               ⚠대가: ★56 절단면이 프리즈 방에서 **둘은 고리(annulus), 셋은 꽉 찬 원판**으로 갈린다.
//                한 방에서 다섯이 나란히 비교되는 자리라 이 차이가 눈에 띈다 — 로컬 판정 항목.
//                단 ★61에선 이 둘(고리)이 곧 '들고 나는 관'이라 차이가 **동선의 서명**이 된다(우연 아님).
//   'cut5'    — **절단되는 다섯 전부**. 절단면이 다섯 다 고리로 통일돼 위 차이가 소멸한다.
//               ★★2026.07.24 현도 채택(★63) — 이유는 '통일'이 아니라 **"종잇장처럼 보인다"**였다.
//                살이 없으면 절단면이 두께 0의 모서리라 끊긴 관이 종잇장으로 읽힌다.
//               ⚠구 주석의 "아랫캡은 원판을 유지한다"는 ★63에서 **부분 폐기**: 셋(#−2·#−1·#+1)은
//                원판을 지우고 **난간의 발이 바닥 구멍 마개를 넘겨받는다**(★63 블록). #+2는 발판이라
//                원판 유지(현도 명시: "+2는 아래 캡 뚫지 마"), #0은 이미 ★62 칼라가 맡고 있다.
// ★68 보어 패싯(2026.07.25) — 관 **안쪽면만** 평평한 법선을 줘서 정10각이 읽히게 한다.
//  근거: 안쪽면은 §1 LOCKED(바깥면 72기 동일)의 대상이 아니다(살이 다섯 기에만 있어 이미 다르다).
//  ⚠false로 되돌리면 구판(안쪽도 매끈 = 원통)으로 돌아간다 — 한 줄 되돌리기.
// ★68-2 계단 난간(2026.07.25, 현도 "끊기는 것 · 사다리꼴인 것 두 가지가 불편") —
//  벽을 따라가던 것을 **계단에 붙인다.** |z|가 상수라 두 줄이 정확히 평행하고 한 번도 안 끊긴다.
//  ⚠성립 조건(실측): 계단 구간 관 최소 반폭 **1.69**(배 x259) > 난간 바깥끝 1.0+0.45 = **1.45**. 여유 0.24.
// ★69 관 바닥에서 띄우기(2026.07.25, 현도 제안) — "무릎길 초반이 너무 폭이 좁다.
//  몸을 관 바닥에서 띄우면 모든 게 해결될 것 같은데? 폭도 일정하게 맞출 수 있고, 텍스트의 장소도 확보할 수 있고."
//  ★★근본 원인이 맞았다: 배 구간(x≈259)에서 보행면이 관 바닥에 붙어 벽 반폭이 **1.69**까지 좁아졌고,
//   그래서 ⓐ 난간이 계단 쪽으로 당겨지고 ⓑ 텍스트 선반이 0.10까지 사라졌다.
//  ★해법은 클램프 하나다. 필요 반폭 W가 정해지면 **허용 최대 깊이 d = √(R²−W²)**가 따라 나오고,
//   스파인을 그 깊이로 클램프하면 전 구간에서 반폭 W가 보장된다. ③F·③G 블렌드는 그대로 두고
//   **못 내려가게만** 막는 것이라 상류 결정을 최소로 건드린다.
//  ⚠대가(실측): W 3.2 → 최대 들림 0.85 · 스파인 최대경사 35.4°→**35.6°**(거의 불변).
//   W 4.0은 ⛔ — 스파인이 41.7°가 돼 flight(40°)보다 가팔라지고 그러면 참이 한 곳도 못 선다.
export const KW_MIN_HALFW = 3.20   // 보행면 높이에서 보장되는 관 반폭(계단 1.0 + 선반 + 난간)
export const KW_MIN_MARGIN = 0.10  // 클램프 여유 — 몸 상면 오프셋·secθ 근사 오차 보정(검증 T절이 실제 폭을 잰다)
export const KW_RAIL_ON = true
export const KW_RAIL_H  = 0.70   // 난간 높이(보행면 기준). 벽이 5~11 서는 단면에서 읽히는 크기
export const KW_PLINTH_T  = 0.55   // 난간 두께(바닥 안쪽으로)
//  ★69: 난간이 **상수 |z|**로 선다 — 클램프가 반폭 KW_MIN_HALFW를 보장하므로 벽을 따라갈 이유가 없어졌다.
//   |z| ∈ [KW_MIN_HALFW−KW_PLINTH_T, KW_MIN_HALFW] = [2.65, 3.20] → 두 줄 정확히 평행 · 전 구간 연속.
//   ★★텍스트는 난간 **안쪽** 선반에 앉는다(계단끝 1.0 ~ 난간안끝 2.65 = **폭 1.65 상수**).
//    ⚠★68-2가 반려된 이유가 텍스트가 난간 **바깥**으로 밀려 가려지는 것이었는데, 여기서는 안쪽이라
//     걸으며 바로 옆에서 읽힌다 — 같은 '상수 난간'이지만 자리가 반대다.
//  ⚠구판이 3토막 난 원인이 **이 틈 0.35**였다(요구 1.0+0.55+0.35 = 1.90 > 배 구간 벽 반폭 1.69).
//   0.10으로 줄이고 안쪽끝 clamp를 더해 **한 줄로 연속**시킨다 — 자리가 좁으면 난간이 계단에 가까워질 뿐 안 사라진다.
export const KW_PLINTH_GAP = 0.10
export const RIB_BORE_FACET = true
export const RIB_WALL_END_CAP = true      // 관 위·아래 끝(y0·y960)을 고리 마구리로 닫는다 — 솔리드 CSG의 전제(열린 몸엔 감산이 파탄)

// ══ ★58 중세 나선(vice) — 기둥 + 꽉 찬 쐐기(2026.07.24 · 현도 스케치·확정) ══
//  왜: 지금 나선은 폭 1.5 디딤판이 보어 폭 5.50 중 **27%만** 쓰며 허공을 감고 오른다(실측). 헐겁다.
//   중세 성탑의 vice처럼 **축에 두꺼운 기둥(newel)을 세우고, 기둥면에서 관 내벽까지 꽉 차는 부채꼴
//   쐐기**로 바꾼다. 현도 스케치의 방사선이 그 쐐기 분할이다.
//  ⚠스케치의 아치형 창(벽 개구)은 **이번 범위 아님**(현도 명시 — 나중 작업).
//
//  ★★세로가 셋으로 갈린다 — 그리고 그 경계가 곧 논증이다:
//   y0~74      기둥만(계단 없음) — 문 아래. 기둥이 지면에 접지(§2-D ① 뿌리)
//   y74~166    vice — 기둥 + 벽 + 쐐기. 완전히 받쳐진 구간
//   y166~210.5 **기둥도 벽도 없다**(★56 절단·프리즈 방) → 얇은 판으로 되돌아간다
//  ⚠y166은 현도 지정값인데, ★56 절단의 아랫끝과 **정확히 같은 지점**이다. 바닥·벽·기둥 셋이 한
//   높이에서 동시에 끝나고 계단만 혼자 올라간다 = 1p7("아무것에도 의존하지 않는다")의 몸.
//   → **판 종류는 기둥의 유무로 갈린다**는 한 줄 규칙. 이 커플링을 끊지 말 것(끊으면 경계가 임의가 된다).
export const RIB_VICE_ON   = true    // 스위치(폐기 = 한 줄 — 전 구간 구판 얇은 판으로 복귀)
export const RIB_NEWEL_R   = 2.0     // ★기둥 반경(현도 "답답하지 않을 정도"). 디딤 길이 3.5 · 보행선 going 0.59
//  ⚠상한 = 보행 폭. 2.8이면 디딤 2.7로 좁아지고, 1.2면 기둥이 가늘어 vice가 안 읽힌다. 검증이 범위를 잡는다.
export const RIB_NEWEL_Y0  = 0       // ★기둥 밑끝 = 지면(현도 지정 — "지면까지 내리자"). 관 밑 마구리에 접지
export const RIB_NEWEL_Y1  = FR_FLOOR_Y   // ★기둥 윗끝 = 프리즈 방 바닥(현도 지정) = ★56 절단 아랫끝
export const RIB_VICE_SOFFIT = 'helix'  // ★★밑면 어법(현도 판정 = '다' = helix):
//   'helix' — 밑면을 깎아 **한 줄로 잇는다** → 나선 볼트. 진짜 중세 vice(노트르담·성벽 탑).
//             §2-D ② "매스 + 깎인 밑면"의 문자 그대로. ㊷ 다섯 날·★54 월대 밑곡선과 같은 어휘 계승.
//   'step'  — 밑면이 거꾸로 된 계단(각 단이 제 단높이만큼 속 찬 덩어리). helix의 기울기를 0으로 둔 꼴.
export const RIB_VICE_T    = 0.5     // ★쐐기의 **가장 얇은 곳**(진행 방향 앞 모서리) 두께.
//  ⚠'helix'에서 두께는 쐐기 하나를 가로질러 정확히 STEP_RISE(0.35)만큼 변한다 — 앞 0.5 / 뒤 0.85.
//   밑면이 상면보다 완만하게(=피치와 나란히) 흐르기 때문이고, 이게 vice가 vice로 보이는 이유다.
//   이 값이 곧 얇은 쪽 두께이므로 0보다 크기만 하면 기하는 성립한다. 다만 0.2 아래면 앞 모서리가
//   칼날이 되어 석조로 안 읽힌다(§2-D ③ 두께 위계) — 검증이 0.2를 하한으로 잡는다.
export const RIB_VICE_NA   = 4       // 쐐기 하나의 원주 분할(내·외 곡면 매끄러움). 1단 = 9°라 4면 충분
export const RIB_VICE_R_OUT = (SHELL_RIB_R - (RIB_WALL_ON ? RIB_WALL_T / 2 : 0)) * Math.cos(Math.PI / RIB_RADIAL_SEG) - 0.05
//  ★파생 — 쐐기 바깥끝. **벽 살의 한가운데까지 물린다**(융착: 실제 vice도 디딤이 벽에 박혀 있다).
//  ⚠상한은 바깥면 평면(SHELL_RIB_R·cos(π/N) = 5.706) — 넘으면 쐐기가 관 바깥으로 뚫고 나온다. 검증이 잡는다.
export const RIB_POLE_ON   = false   // ★구 1p7 폴 절단 device — **철거 확정(현도 2026.07.24)**.
//  ⚠상수(POLE_R·POLE_CUT_F·Y_POLE_CUT)는 남긴다: 웨이포인트·검증이 참조하고, 기둥이 그 자리를
//   삼키므로 되살릴 일도 없다. '폐기 = 경로에서 제거이지 코드 삭제가 아님'(㊾ 전례).

// ══ ★60 문지방(sill) — 나선 ↔ 프리즈 방 바닥의 매듭(2026.07.24) ══
//  ⚠**이건 미적 디테일이 아니라 결함 수리다.** 실측(2026.07.24 세션 시작):
//   마지막 쐐기 바깥끝 r5.55 · 방 바닥 모서리 r6.40 → 그 사이 **0.85의 환형 허공**이 나선 우물을
//   빙 두르고 있었다. 즉 나선에서 방 바닥으로 **내려설 수가 없었다**.
//   그러면 §5의 "방으로 나와 다섯이 떠 있는 것을 본다"도, ★56 주석의 "관람자는 그걸 **아래에서
//   올려다본다**"도 물리적으로 성립하지 않는다 — 1p7이 '지나가며 곁눈질'로 축소된다.
//   (바닥에 서지 못하면 다섯의 밑을 한 화면에 못 넣는다. 윗토막 밑끝이 174~191로 흩어져 있어서,
//    나선 위 어느 높이에 있든 늘 일부는 발밑이고 일부는 머리 위다.)
//
//  ★어휘 = §2-D ③ "시작·끝은 문지방/착지 블록으로 맺는다 · 두께 위계 = 걷는 것 < 받치는 것 < 매듭".
//   그래서 혀는 쐐기보다 **두껍다**(FR_SILL_T > 쐐기 평균 0.675). 뿌리(§2-D ①)는 **③지지체** —
//   프리즈 매스(바닥)가 안쪽으로 손을 내민 것이지, 새로 띄운 판이 아니다.
//  ★★왜 부양 판(0.35 라임)이 아닌가 — 이게 이 방에서만 뒤집히는 규칙이다:
//   §2-B '부양 판 라임'은 뜸이 **드문 사건**일 때 의미가 있다. 그런데 이 방에서 '떠 있음'은
//   **리브 다섯의 술어**다(1p7). 바닥 부재까지 떠 있으면 뜸이 방의 기본값이 되고, 다섯의 뜸이
//   배경으로 가라앉는다. 매듭은 확실히 받쳐져 있어야 리브의 안 받쳐짐이 도드라진다.
//
//  ⚠**불가시 조건(R9절이 강제)**: 혀는 바닥 살(y164~166) 안에 머문다. 아치 크라운이 y164이고
//   그 아래는 홀에서 올려다보이는 아치 터널이므로, 혀 밑면이 164를 내려가면 **홀에서 보인다** =
//   1p5 파사드에 정체불명의 혹이 달린다. 두께 상한이 미학이 아니라 봉인인 이유.
export const FR_SILL_ON   = false  // ⚠★62가 흡수(2026.07.24 현도 판정) — 18° 혀 → 360° 칼라 + 반원 착지판.
//   코드·노브는 남긴다(폐기 = 경로에서 제거이지 삭제 아님 — ㊾ 전례). 되돌리려면 이 줄 true + FR_KNOT_ON=false.
export const FR_SILL_SPAN = 2      // ★각폭 = 쐐기 각폭(9°)의 배수. 2 → 18°, 바닥 모서리에서 호 ≈2.1
//  ⚠크게 하면 아래 단(마지막 쐐기의 뒤쪽)을 덮는다 — 혀는 r5.15 바깥만 쓰므로 덮이는 건 쐐기의
//   바깥 사면뿐이지만, 4를 넘기면 머리 여유가 실제로 죽는다. R9절이 상한을 실측으로 잡는다.
export const FR_SILL_IN   = 0.4    // 쐐기 쪽 물림(안쪽) — 겹쳐야 발밑에 틈이 없다(레이캐스트 헤어라인 방지)
export const FR_SILL_BITE = 0.3    // 바닥 쪽 물림(바깥) — 구멍 모서리를 넘어 물린다. 캡 중심 어긋남 0.054보다 크게
export const FR_SILL_T    = 0.9    // ★두께 = 매듭 위계(쐐기 평균 0.675 < 0.9). 상한은 봉인(밑면 > y164)
export const FR_SILL_LIFT = 0.02   // 바닥 상면 위 부양 — 동일평면 z-fighting 회피(RibCutCaps의 +0.02와 같은 관례)
export const FR_SILL_MAT  = 'floor'  // ★재질(현도 판정 항목) — 'floor'(프리즈 석재 = 바닥이 손을 내민 것)
//   ↔ 'tread'(디딤판 어휘 = 계단이 발을 내민 것). 어느 쪽이 주어인가의 문제라 미적 판정은 현도 몫.

// ══ ★61 리브 갈아타기 — 두 리브의 여정(2026.07.24 현도 결정 · 티켓 3/3) ══
//  왜: 구 설계는 올라온 리브(#0)를 그대로 계속 타서 프리즈 방이 '통로'가 됐다(현도 진단 —
//   "방을 탐사할 시간이 없다"). 해법 = 올라온 리브와 올라갈 리브를 **분리**한다:
//   #0로 방 바닥에 내려서고(★60 문지방이 그 출구) → 방을 걸어서 건너며(#0↔#+2 실측 50.2,
//   그 중간에서 1p7 비석) → 목적지 리브의 **떠 있는 관 아가리**로 자립 나선을 타고 들어가 계속 오른다.
//  ★철학 = 독해 (ㄴ, 현도 07.24): "같은 무한을 **다른 실체에서 다시** 만난다" — 1p8("**모든** 실체는
//   필연적으로 무한하다")의 '모든'이 처음으로 몸으로 읽힌다. 이행(1p9·10)의 선취가 아니라 1p8 보강.
//  ★★기하가 깨끗한 이유 — **새 개구 0**: 목적지 리브는 ★56으로 이미 끊겨 떠 있고, 살 있는 관(★57)의
//   절단면은 저절로 '고리'다 = 밑이 뚫린 아가리. 윗캡을 안 다는 것뿐, 바깥면 관통이 없다
//   → LOCKED 예외 #3(바깥면 불변) 무손상 · 예외 #1(문) 무증가. 늘어나는 건 RIB_WALL_SCOPE 1→2뿐.
export const RIB_XFER_ON  = true     // 스위치(폐기 = 한 줄 — false면 구 단일 리브 여정으로 복원:
//   상부가 #0 관 안으로 돌아가고 자립 나선·비석·회전이 전부 꺼진다. Dome·App·waypoints가 공유)
export const RIB_DEST_K   = 2        // ★목적지 리브(현도 확정 07.24: #+2) — 근거: 횡단 50.2(걸어 건널 맛)
//   + 회랑이 신전 복합체에서 멀어짐. 대안 #−2는 회랑이 신전 위를 지난다(여유 36 — 조감이 바뀜).
export const RIB_DEST_PHI = RIB_DEST_K * 2 * Math.PI / MERIDIANS   // = +10° (hallDoors phi와 같은 식)
//  ★상부 여정(무릎길~테라스 문)은 App.jsx에서 그룹 하나로 rotation-y = −RIB_DEST_PHI 회전 —
//   10° = 리브 간격(5°)의 정확히 2배라 **리브 격자가 자기 자신 위로 겹친다**: 회랑↔리브 상대기하 불변,
//   보이는 리브의 k 라벨만 +2 이동(검증 K·O절이 재확인). 상부는 전부 φ=0 평면 좌표라 회전이 싸다.
// ══ ★85 테라스 재설계 = 아가리를 받는 환형 부채꼴 (2026.07.29 현도 지시 · 덩어리 블록아웃) ══
//  현도: *"나팔 통로 끝부분에 원래 있던 테라스 형태인 반원호를 설치하자. 끝에 딱 맞게.
//   그 반원호는 돔의 중심에서 0번 리브를 이은 반지름까지만."*
//  → ★80이 만든 **선언된 빚**(TERRACE_ON=false · UNASSIGNED=[6,12,13,14,15] · DoD-2 미충족)의 상환 착수.
//
//  ★★"끝에 딱 맞게"가 **공짜로 떨어진다**(실측이 준 선물, 튜닝값 아님):
//   아가리는 진행 방향이 돔 중심 **정조준**(각차 0.0000° — ★80이 닫힌 식에서 유도)이라
//   문턱이 반경에 수직인 **직선 현(弦)**이고, 그래서 두 모서리가 **같은 반경**(142.543)에 선다.
//   바깥 림을 그 반경으로 잡으면 **호 하나가 두 모서리를 동시에 꿴다.**
//   현과 호 사이 초승달(가운데 깊이 1.410 · 양 끝 0)이 문턱 바로 앞을 메운다 → 틈 0 · 돌출 0.
//   ⚠이 성질은 `RM10_FLARE_*` 노브를 돌려도 유지된다(정조준이 닫힌 식이므로). 검사가 매 실행 재유도한다.
//
//  ★좌표계 = **상부 여정 그룹 로컬**(App `<group rotation-y={-RIB_DEST_PHI}>` 안 · 월드 = 로컬 +10°).
//   그러므로 **리브 #0(월드 방위 0° = 드럼 축 = 현도가 말한 "대칭선")의 반지름선 = 이 좌표계에서 −10°.**
//   부채꼴은 그 선에서 시작해 아가리 먼 모서리까지 돈다.
//
//  ★두께(현도 위임 — 구조 판단): `TERRACE_T = 2.5 × PASS_T`. 맞닿는 바닥판(회랑·나팔)이 0.60이라
//   같은 값이면 '통로 바닥의 연장'으로 읽힌다. 2.5배여야 **다른 덩어리**가 된다.
//   위계(§2-D ③ 걷는 것 < 받치는 것 < 매듭): 전망 반원판 1.2(★71-2가 0.35 종잇장에서 올린 값) < 1.5 < 매듭 2.6.
//   ⚠구 테라스는 **두께 0 링 한 장**이었다 — '판떼기' 진단(㊿)의 표본.
//
//  ⚠**밑이 비어 있다는 사실은 이 블록이 못 푼다.** y238.43에서 껍질까지 85.76 · 회랑은 같은 레벨.
//   §2-D ① 뿌리 셋 중 현재 답 = **"의도된 부양 — 잠정"**이고, 그건 결정이 아니라 **미룸의 선언**이다.
//
//  ⚠구 링(`TERRACE_RIN/ROUT/ARC/Y` — ★79-5 출구 통로 파생)은 ★80이 폐기했다. 상수·검사는 **보존계**로
//   남기되(치수를 지우면 되살릴 근거가 사라진다 — ST_ON 전례), **그리는 것은 이 블록**이다.
//   구 링을 재는 검사 절은 `!RM10_FLARE_ON` 스위치 뒤로 들어갔다(check_corridor K2·K3⑦).
export const TERRACE_ON  = RM10_FLARE_ON   // 새 테라스는 아가리에서 파생된다 — 나팔이 있어야 존재한다
export const TERRACE_T   = 2.5 * PASS_T    // 1.50 판 두께(위 근거)
export const TR_BITE     = 0               // 아가리 물림. 0 = 호가 두 모서리를 정확히 꿴다(초승달이 이미 겹침을 준다)
export const TR_ROUT     = terraceMouth().rOut + TR_BITE        // 142.543 — 두 모서리를 꿰는 호(바깥 림 = 아가리가 못 박는다)
export const TR_Y        = RM10_FLARE_MY                        // 238.43 = 아가리 바닥 = 회랑 바닥(무단차)
// ★★★85-2 수정 ①(현도 2026.07.29): **리브 #0 선에서 끝내지 말고, 그 선을 축으로 대칭이 될 때까지 연장.**
//  *"0도에서 테라스를 봤을 때 딱 대칭이 되도록"* → 부채꼴이 **월드 ±(아가리 먼 모서리 방위)** = ±41.568°가 된다.
//  ⇒ 리브 #0 반지름선(월드 0°)은 이제 부채꼴의 **끝이 아니라 정중앙**이고, 호가 정확히 **2배**로 늘어난다.
//  ⚠거울 반쪽(월드 −41.57°~0°)에는 개구가 하나도 없다 — 순수한 판. 아가리는 한쪽에만 있다.
//  ⚠대칭축이 리브 #0라는 사실이 이 형태의 유일한 근거다. 리브 #0는 드럼 축이기도 하므로
//   테라스는 **아래 세계(1p5 홀)의 축 위에** 걸린다 — 조형 의미는 현도 몫, 여기선 기하만 못 박는다.
export const TR_AZW      = terraceMouth().azHi + RIB_DEST_PHI   // 월드 방위 상한 = 아가리 먼 모서리(+41.568°)
export const TR_AZ1      = TR_AZW - RIB_DEST_PHI                // 로컬 +31.568° (아가리 쪽 끝 — 무변)
export const TR_AZ0      = -TR_AZW - RIB_DEST_PHI               // 로컬 −51.568° (거울 끝 — ★85-2 신설)
// ★★★85-2 수정 ②(현도): **폭 노브.** 바깥 림은 아가리가 못 박으므로("딱 맞게"), 폭은 **안쪽 림이 움직여** 만든다.
//  기준 = 구 링 폭(TR_ROUT − 129.6 = 12.94). 배율 하나로 왕복한다 — 한 줄 교체 + 하드 리로드.
//  ⚠**대가는 아가리 앞 깊이다**(실측): 문턱 중앙 r141.13에서 안쪽 림까지 —
//   1(폭 12.94) → 11.53 · **2/3(8.63) → 7.21** · 1/2(6.47) → 5.06. 폭 40짜리 문 앞의 발디딤이 이 값이다.
//  ⚠하한: 안쪽 림이 문턱 중앙(141.13)을 넘으면 **문 앞이 허공**이 된다 ⇒ 폭 > 1.41(검사가 박는다).
export const TR_W_F      = 2 / 3           // ★✅현도 확정 2026.07.29(폭 8.63 · 아가리 앞 깊이 7.22). 대안 = 1(구 링 그대로) / 0.5 — 한 줄 교체로 복귀
export const TR_W_BASE   = TR_ROUT - TERRACE_RIN                // 12.94 = 구 링 폭(계보 보존 — 배율 1이면 구판 그대로)
export const TR_W        = TR_W_BASE * TR_W_F
export const TR_RIN      = TR_ROUT - TR_W                       // 안쪽 림이 움직인다(바깥 림 고정)
//  호 분할 = 세그 길이 ≈1.1 유지(대칭 연장으로 호가 2배가 됐으므로 고정값이면 성겨진다)
export const TR_SEG      = Math.max(96, Math.round(TR_ROUT * (TR_AZ1 - TR_AZ0) / 1.1))
//  아가리 문턱의 두 모서리 — **등불 방 로컬 → 상부 여정 그룹 로컬**로 옮겨 반경·방위를 잰다.
//  ⚠`flareSpec()`의 마지막 정거장과 같은 점이어야 한다. 사본이 되지 않도록 **검사가 매 실행 대조**한다
//   (check_waypoints F절 — ★83 `axisDistMatches` 전례와 같은 형식).
export function terraceMouth () {
  const f1 = RM10_ARC_TH1 + Math.PI - RM10_FLARE_SWEEP          // flarePoint(s=SWEEP)의 위상
  const nx = -Math.cos(f1), nz = -Math.sin(f1)                  // 폭 방향(단위)
  const hw = RM10_FLARE_W1 / 2                                  // 20
  const AX = RM10_AX_R * Math.cos(RM10_PHI), AZ = RM10_AX_R * Math.sin(RM10_PHI)
  const c = Math.cos(-RM10_PHI), s = Math.sin(-RM10_PHI)        // three rotation-y(−RM10_PHI)
  const up = (x, z) => [x * c + z * s + AX, -x * s + z * c + AZ]
  const ctr = up(RM10_FLARE_MX, RM10_FLARE_MZ)
  const cor = [1, -1].map((sg) => up(RM10_FLARE_MX + sg * hw * nx, RM10_FLARE_MZ + sg * hw * nz))
  const az = cor.map((p) => Math.atan2(p[1], p[0])), rr = cor.map((p) => Math.hypot(p[0], p[1]))
  return {
    ctr, ctrR: Math.hypot(ctr[0], ctr[1]), ctrAz: Math.atan2(ctr[1], ctr[0]),
    corners: cor, cornerR: rr, cornerAz: az,
    rOut: Math.max(rr[0], rr[1]),           // 두 모서리는 같은 반경이어야 한다(검사가 잰다)
    azLo: Math.min(az[0], az[1]), azHi: Math.max(az[0], az[1]),
    w: RM10_FLARE_W1, h: RM10_FLARE_H1, y: RM10_FLARE_MY,
  }
}

export const FREE_MOUTH_CLR = 0.6    // 자립 나선 기둥 윗끝 ↔ 아가리(절단면) 세로 여유 — 마지막 쐐기

// ★62-2 자립 구간의 어휘 — 하나로 통일(2026.07.24 현도 판정: "2개가 섞여 있잖아?")
//  구 ★61은 방 허공 구간을 ★58 어휘(기둥+쐐기)로, 아가리 위를 구판 얇은 판으로 올렸다.
//  → 한 리브(#+2)의 계단이 중간에 어휘를 갈아타는 셈이라 **현도 반려**. 통일 = **부양 판**.
//  ★근거가 이미 있었다(§2-B '부양 판 라임' · ★58 한 줄 규칙 "판 종류는 **기둥의 유무**로 갈린다"):
//   자립 구간에는 기둥이 없어야 자연스럽다 — 기둥을 세운 순간 그 규칙을 우리가 어긴 것이었다.
//   방 허공에 받치는 것 없이 떠서 오르는 판 = 1p7 '증명된 뜸'과 같은 말이고, 목적지 리브가
//   떠 있다는 사실과도 한 어휘가 된다(계단도 리브도 안 받쳐져 있다).
//  ⚠대가: ★60/★62 매듭 주석의 "매듭은 받쳐져 있어야 리브의 안 받쳐짐이 도드라진다"와 긴장.
//   단 그 논거는 **바닥 매듭**(칼라·착지판 = 여전히 받쳐짐)에 대한 것이고, 계단은 원래 뜬 어휘다.
export const RIB_FREE_MODE = 'plate'   // 'plate' = 부양 판 통일(현도 확정) · 'vice' = ★61 원안(기둥+쐐기)

// ══ ★63 끊긴 다섯을 열다 — 위아래 관통 + 우물 발코니 (2026.07.24 현도 판정) ══
//  현도: "이동 가능한 +2와 0을 빼면 전부 방에서 보았을 때 위아래가 막혀 있다. 그거 전부 뚫고,
//   뚫린 경선의 테두리에는 낮은 발코니처럼 감싸달라. 그리고 종잇장처럼 안 보이게 두께를."
//
//  ★한 수로 둘이 풀린다 — `RIB_WALL_SCOPE`를 'explore'(여정 2기) → **'cut5'(다섯 전부)**:
//   ① 다섯 다 살(0.22)이 붙어 절단면이 **저절로 고리**가 된다(= 두께가 보인다. ★57·★61과 같은 원리)
//   ② `RibCutCaps`의 윗캡 조건이 이미 "살 없는 관만 막는다"라 **윗캡 셋이 자동 소멸**한다.
//  ⚠LOCKED 무손상: ★57 살은 **안쪽으로만** 붙고 바깥면은 72기가 같은 TubeGeometry 그대로다.
//   예외 대장에서 늘어나는 건 `RIB_WALL_SCOPE` 2기 → 5기뿐이고, 바깥에서는 아무 차이도 안 보인다.
//
//  ★아래는 캡을 못 지운다 — 지우면 뚫린다: 아랫캡(r6.52)이 **바닥 관통 구멍 r6.40의 마개를 겸한다**
//   (★56). 그래서 원판을 지우는 대신 **난간의 발을 바닥 살에 묻어** 그 일을 넘겨받는다
//   (밑면 165.12 > 아치 크라운 164 = 홀에서 불가시. ★60·★62와 같은 봉인 규칙).
//  ⚠**깊이 166의 수직 샤프트가 열린다**(아랫토막은 지면부터 통짜 관). 난간은 장식이 아니라 그 대응이다.
//  ⚠**문 복원과 배타**: `HALL_DOORS_ON=true`가 되면 방 → 샤프트 → 문 → 홀로 시선이 뚫린다.
//   지금은 문이 소등이라 안전하고, R9-3절이 그 조합을 실패로 잡는다(다음 세션이 모르고 켜는 것 방지).
//
//  ★발코니 = 현도 (b)안: 구멍 둘레가 **한 단 올라서고**(BAL_STEP) 그 위에 난간이 선다.
//   걸어가다 한 단 올라서서 내려다보는 몸짓이 생긴다. 난간은 **이음매 없는 속 찬 고리** —
//   난간 동자(баluster)는 §2-C 세로 요소 장부(리브만 실체) 위반이라 못 쓴다.
//  ⚠난간은 바닥에만 있다. **떠 있는 윗토막에 절대 안 닿는다**(최소 간극 9.6 = #−2) — 닿는 순간
//   1p7('받쳐지지 않음')이 죽는다. 이건 미학이 아니라 명제 조건이다.
// ★64-2 관통 구멍 여유 — 구멍이 리브를 따라가게 된 뒤로는 **넉넉할 이유가 없다**.
//  구 0.4(TEMPLE_CLR)는 수직 원기둥이 기운 리브를 품으려던 여유였다. 이제 헤어라인만 남긴다
//  ⇒ **틈을 물건으로 덮는 대신 틈 자체를 없앤다**(현도 07.24: "엉성하게 막으면 투박해 보인다").
//  ⚠0으로 두면 면이 겹쳐 CSG·z-fighting이 깨진다. 0.05~0.15가 실용 범위.
export const RIB_HOLE_CLR = 0.08

