export const BAL_PARA_H   = 1.0    // 난간 높이(발코니 상면 기준). 기대는 높이지 넘는 높이가 아니게
export const BAL_RIM_IN   = 5.4    // 난간 안쪽 = 관 내벽(5.50) 살짝 안 — 물려야 발밑에 헤어라인이 없다
//   몸통이 관 살(고리 테두리)과 안 닿게. 이 위 1~2칸은 얇은 판이 아가리를 꿰며 들어간다
//   (한 줄 규칙 '판 종류는 기둥의 유무' 유지 — 기둥이 끝나는 자리부터 판).
//  ★자립 나선 = ★58과 **같은 어휘·같은 기계**(기둥 + 부채꼴 쐐기, fanSolid·buildViceWedge 재사용).
//   차이는 '관이 없다'뿐 — "저기 나선이 나 있는 것을 본다"(현도)가 방 허공에 선 vice 그 자체다.
//   기둥은 곧음·고립·접지(§2-C) — 목적지 리브의 바닥 절단면 캡(원판) 위에 선다.
// ── 1p7 비석(횡단 경로 위) — ⚠자리 미정(현도 07.24): 노브로 세 자리 왕복 판정 ──
