//   0.5 = 한가운데(기본 — ★61 서술 "그 중간에서 읽고") · 1 = #+2 발치. 임의 실수 가능.
//   ⚠부수 발견(실측): 횡단 직선이 #+1 바닥 절단면 원판(중심 이격 1.1)을 밟고 지난다 —
//    "끊긴 밑동을 밟고 건넌다"(막힘 없음 · 윗토막 y179는 머리 위). 의도 승격 여부 = 현도.
export const STELE7_OFF = 3.2        // 경로 중심선에서 서쪽(−x·돔 중심 쪽)으로 비켜 세움 — 동선 안 막게

// ══ ★62 바닥 매듭 — 반원 착지판 + 고리 칼라 (2026.07.24, 현도 로컬 판정 후속) ══
//  현도 지시 2: ① "올라오는 부분을 반원형으로 덮어서 제대로 올라올 수 있게" ② "리브와 방 사이
//  저 틈들 보기 안 좋다 — 틈 없게". ★60 문지방(18° 혀)을 **흡수·대체**한다(FR_SILL_ON=false).
//
//  ★실측이 밝힌 ②의 정체: 방 바닥 관통 구멍은 r**6.40**(=SHELL_RIB_R+TEMPLE_CLR)이고 관 바깥은
//   r**6.00** → **0.40 폭 링 슬롯이 360° 열려 있었다.** 넷은 아랫캡(r6.52)이 마개인데 **#0만
//   캡에서 제외**돼 있다(나선이 지나므로 — RibCutCaps의 `k!==0` 필터). 바닥 살은 y164~166
//   두 겹뿐이고 그 아래는 아치(크라운 164) = 홀이므로, 이건 장식적 틈이 아니라 **홀까지 뚫린
//   구멍**이었다. ★56의 "아랫캡이 바닥 구멍 마개를 겸한다"가 #0에서만 성립하지 않았던 것.
//
//  ★두 부재로 나눈 이유(반원판 하나로 안 되는 이유):
//   · **칼라(360°)** = 봉인 담당 — 링 슬롯(6.00~6.40)과 환형 허공(5.55~6.40)을 방위 무관하게 막는다.
//   · **착지판(180°)** = 착지 담당 — 우물의 **절반만** 덮는다. 나머지 반은 열어 두어 **올라온
//     나선이 그대로 내려다보인다**(현도 확정). 둘을 합치면 도착 쪽은 축~바닥까지 온전한 반원,
//     반대쪽은 우물 + 테두리.
//
//  ⚠착지판 방향은 미학이 아니라 **기하가 정한다**: 마지막 쐐기의 *진행 쪽* 모서리에서 앞으로 180°.
//   반대로 돌리면 판 밑면(166.02−0.9 = 165.12)이 마지막 쐐기 상면(165.975)보다 낮아 **쐐기 셋을
//   파묻는다** = 올라오는 길이 막힌다. 부수 확인(실측): 그렇게 정해진 반원의 중심 방위 112.5°가
//   #+2로 건너가는 방향 95.0°와 17.5°밖에 안 어긋난다 — 올라서면 반원이 이미 건너갈 쪽을 향한다.
//
//  ⚠불가시 조건은 ★60과 동일: 밑면 165.12 > 아치 크라운 164(홀에서 안 보인다). R9절이 강제.
//  ⚠치수 정본은 ★60 노브를 그대로 쓴다(FR_SILL_T 두께 · FR_SILL_LIFT 부양 · FR_SILL_IN 안쪽 물림
//   · FR_SILL_BITE 바깥 물림 · FR_SILL_MAT 재질) — 매듭이 둘로 갈렸을 뿐 위계는 한 곳에서 정한다.
